svg.script:
// ============================================================
// 00 // BOOT CONSTANTS
// ============================================================
var CX = 960, CY = 540, FOC = 1050;   // FIXED origin, never recentered
var ARENA_R = 6.5;
var T = 0;
var DL = [];                          // draw list
var PL = null, EN = null;
var PRE = [null, null];               // character select previews
var FLASH = 0, SHAKE = 0, BANT = 0, MVT = 0;
var SPARKS = [], RINGS = [], PROJ = [];
var PADS = [], PDP = [[], [], [], []], PADN = 'KB';
var TOUCHON = false, TAP = false, IGN = 0;
var VI = 0;
var KEYS = {}, KEDGE = {};

// cached DOM
var EL = {}, ELBUF = [], SR = [], SS = [];
var ACACHE = {};
var XL = 'http://www.w3.org/1999/xlink';
var ROT = [0, 1, 2];                  // newest, mid, oldest buffer ids

function $(id){ return document.getElementById(id); }
function setTxt(el, s){ if(el && el.textContent !== s){ el.textContent = s; } }
function sA(el, attr, val){
  var k = el.id + '|' + attr;
  if(ACACHE[k] !== val){ ACACHE[k] = val; el.setAttribute(attr, val); }
}
function setBuf(el, v){
  if(el.getAttribute('href') !== v){
    el.setAttribute('href', v);
    try{ el.setAttributeNS(XL, 'xlink:href', v); }catch(e){}
  }
}
function kD(c){ return !!KEYS[c]; }
function kE(c){ return !!KEDGE[c]; }
function KSET(c, v){
  if(v && !KEYS[c]){ KEDGE[c] = true; }
  KEYS[c] = v;
  if(v){ try{ var a = audio(); if(a && a.state === 'suspended'){ a.resume(); } }catch(e){} }
}

var GAME = {
  state: 'title',
  mode: '1p',              // '1p' campaign vs CPU, or '2p' local versus
  ei: 0,
  oppList: [],
  round: 1,
  plw: 0,
  enw: 0,
  timer: 60,
  introT: 0,
  koT: 0,
  nextT: 0,
  selT: 0,
  fightShown: false,
  paused: false,
  p1sel: 0, p2sel: 1, p1lock: false, p2lock: false
};

// adaptive quality
var FPS = { acc: 0, n: 0, low: false };

// ============================================================
// 01 // MATH
// ============================================================
function sub(a,b){ return [a[0]-b[0], a[1]-b[1], a[2]-b[2]]; }
function add(a,b){ return [a[0]+b[0], a[1]+b[1], a[2]+b[2]]; }
function mul(a,s){ return [a[0]*s, a[1]*s, a[2]*s]; }
function dot(a,b){ return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]; }
function cross(a,b){
  return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]];
}
function len(a){ return Math.sqrt(a[0]*a[0]+a[1]*a[1]+a[2]*a[2]); }
function nrm(a){ var l = len(a); if(l < 1e-6){ l = 1; } return [a[0]/l, a[1]/l, a[2]/l]; }
function L(a,b,t){ return a + (b-a)*t; }
function LZ(a,b,t){ return [L(a[0],b[0],t), L(a[1],b[1],t), L(a[2],b[2],t)]; }
function clamp(v,a,b){ return v < a ? a : (v > b ? b : v); }
function EO(t){ t = clamp(t,0,1); return 1 - (1-t)*(1-t); }
function EI(t){ t = clamp(t,0,1); return t*t; }
function EZ(t){ t = clamp(t,0,1); return t*t*(3-2*t); }
function rnd(a,b){ return a + Math.random()*(b-a); }
function mid(a,b,t){ t = (t === undefined) ? 0.5 : t;
  return [L(a[0],b[0],t), L(a[1],b[1],t), L(a[2],b[2],t)]; }

// camera orbits a FIXED world target
var CAM = { yaw: 0.6, pit: 0.30, dist: 9.8, tx: 0, ty: 1.2, tz: 0 };
var SHX = 0, SHY = 0;
var VIEWS = [
  { yaw: 0.60, pit: 0.30, dist: 9.8 },
  { yaw: 1.05, pit: 0.14, dist: 8.2 },
  { yaw: 0.35, pit: 0.52, dist: 11.6 },
  { yaw: 0.85, pit: 0.30, dist: 13.8 }
];

function proj(p){
  var dx = p[0]-CAM.tx, dy = p[1]-CAM.ty, dz = p[2]-CAM.tz;
  var cy = Math.cos(CAM.yaw), sy = Math.sin(CAM.yaw);
  var x1 = dx*cy - dz*sy;
  var z1 = dx*sy + dz*cy;
  var cp = Math.cos(CAM.pit), sp = Math.sin(CAM.pit);
  var y2 = dy*cp + z1*sp;
  var z2 = -dy*sp + z1*cp;
  var d = z2 + CAM.dist;
  if(d < 0.35){ d = 0.35; }
  return [CX + x1*FOC/d + SHX, CY - y2*FOC/d + SHY, d];
}

// back face culling : rotation cached per frame
var vCY = 1, vSY = 0, vCP = 1, vSP = 0;
function cacheCamRot(){
  vCY = Math.cos(CAM.yaw); vSY = Math.sin(CAM.yaw);
  vCP = Math.cos(CAM.pit); vSP = Math.sin(CAM.pit);
}
// visible if rotated normal points toward camera (z2 component < 0)
function nvis(nx, ny, nz){
  var z1 = nx*vSY + nz*vCY;
  return (-ny*vSP + z1*vCP) < -0.02;
}

function segSeg(p1,q1,p2,q2){
  var d1 = sub(q1,p1), d2 = sub(q2,p2), r = sub(p1,p2);
  var a = dot(d1,d1), e = dot(d2,d2), f = dot(d2,r), s, t;
  if(a <= 1e-9 && e <= 1e-9){ return len(r); }
  if(a <= 1e-9){ s = 0; t = clamp(f/e,0,1); }
  else {
    var c = dot(d1,r);
    if(e <= 1e-9){ t = 0; s = clamp(-c/a,0,1); }
    else {
      var b = dot(d1,d2), den = a*e - b*b;
      s = den > 1e-9 ? clamp((b*f - c*e)/den, 0, 1) : 0;
      t = (b*s + f)/e;
      if(t < 0){ t = 0; s = clamp(-c/a,0,1); }
      else if(t > 1){ t = 1; s = clamp((b-c)/a,0,1); }
    }
  }
  var c1 = add(p1, mul(d1,s)), c2 = add(p2, mul(d2,t));
  return len(sub(c1,c2));
}

// ============================================================
// 02 // RENDERER PRIMITIVES (with back face culling)
// ============================================================
function poly(pts, col, sw, op, fill, layer){
  var s = '', z = 0, i, p;
  for(i = 0; i < pts.length; i++){
    p = proj(pts[i]);
    s += (i ? 'L' : 'M') + p[0].toFixed(1) + ',' + p[1].toFixed(1);
    z += p[2];
  }
  DL.push({ l: layer, z: z/pts.length,
    s: '<path d="' + s + 'Z" fill="' + fill + '" stroke="' + col +
       '" stroke-width="' + sw + '" stroke-opacity="' + op +
       '" stroke-linejoin="round"/>' });
}

function pline(pts, col, sw, op, layer){
  var s = '', z = 0, i, p;
  for(i = 0; i < pts.length; i++){
    p = proj(pts[i]);
    s += (i ? 'L' : 'M') + p[0].toFixed(1) + ',' + p[1].toFixed(1);
    z += p[2];
  }
  DL.push({ l: layer, z: z/pts.length,
    s: '<path d="' + s + '" fill="none" stroke="' + col +
       '" stroke-width="' + sw + '" stroke-opacity="' + op +
       '" stroke-linecap="round"/>' });
}

function lineSeg(a, b, col, sw, op, layer){
  pline([a,b], col, sw, op, layer);
}

// tapered rectangular frustum between two points, culled faces
function boxSeg(a, b, u, v, wa, da, wb, db, col, caps){
  var dir = nrm(sub(b,a));
  var A1 = add(a, add(mul(u,-wa/2), mul(v,-da/2)));
  var A2 = add(a, add(mul(u, wa/2), mul(v,-da/2)));
  var A3 = add(a, add(mul(u, wa/2), mul(v, da/2)));
  var A4 = add(a, add(mul(u,-wa/2), mul(v, da/2)));
  var B1 = add(b, add(mul(u,-wb/2), mul(v,-db/2)));
  var B2 = add(b, add(mul(u, wb/2), mul(v,-db/2)));
  var B3 = add(b, add(mul(u, wb/2), mul(v, db/2)));
  var B4 = add(b, add(mul(u,-wb/2), mul(v, db/2)));
  if(nvis(-v[0],-v[1],-v[2])) poly([A1,A2,B2,B1], col, 1.7, 1, '#000', 2);
  if(nvis( u[0], u[1], u[2])) poly([A2,A3,B3,B2], col, 1.7, 1, '#000', 2);
  if(nvis( v[0], v[1], v[2])) poly([A3,A4,B4,B3], col, 1.7, 1, '#000', 2);
  if(nvis(-u[0],-u[1],-u[2])) poly([A4,A1,B1,B4], col, 1.7, 1, '#000', 2);
  if(caps){
    if(nvis(-dir[0],-dir[1],-dir[2])) poly([A1,A2,A3,A4], col, 1.7, 1, '#000', 2);
    if(nvis( dir[0], dir[1], dir[2])) poly([B1,B2,B3,B4], col, 1.7, 1, '#000', 2);
  }
}

// auto framed tapered limb segment
function limbTaper(a, b, w1, w2, col){
  var d = sub(b, a);
  var l = len(d);
  if(l < 1e-5){ return; }
  var dir = mul(d, 1/l);
  var ref = Math.abs(dir[1]) > 0.92 ? [1,0,0] : [0,1,0];
  var u = nrm(cross(dir, ref));
  var v = nrm(cross(u, dir));
  boxSeg(a, b, u, v, w1, w1, w2, w2, col, false);
}

// axis aligned box from center + 3 axes, culled faces
function boxCC3(c, u, v, w, sx, sy, sz, col){
  var C = [], i, su, sv, sw;
  for(i = 0; i < 8; i++){
    su = (i & 1) ? 1 : -1;
    sv = (i & 2) ? 1 : -1;
    sw = (i & 4) ? 1 : -1;
    C.push(add(c, add(add(mul(u, su*sx/2), mul(v, sv*sy/2)), mul(w, sw*sz/2))));
  }
  var F = [[0,1,5,4],[3,2,6,7],[0,1,2,3],[4,5,7,6],[0,2,6,4],[1,5,7,3]];
  var NX = [-v[0], v[0], -w[0], w[0], -u[0], u[0]];
  var NY = [-v[1], v[1], -w[1], w[1], -u[1], u[1]];
  var NZ = [-v[2], v[2], -w[2], w[2], -u[2], u[2]];
  for(i = 0; i < 6; i++){
    if(nvis(NX[i], NY[i], NZ[i])){
      var f = F[i];
      poly([C[f[0]], C[f[1]], C[f[2]], C[f[3]]], col, 1.7, 1, '#000', 2);
    }
  }
}

function tri(a, b, c, col){
  poly([a,b,c], col, 1.5, 1, '#000', 2);
}

// pyramid spike pointing along dir
function pyr(c, dir, h, bw, col){
  var ref = Math.abs(dir[1]) > 0.92 ? [1,0,0] : [0,1,0];
  var u = nrm(cross(dir, ref));
  var v = nrm(cross(u, dir));
  var ap = add(c, mul(dir, h));
  var B = [
    add(c, add(mul(u,-bw/2), mul(v,-bw/2))),
    add(c, add(mul(u, bw/2), mul(v,-bw/2))),
    add(c, add(mul(u, bw/2), mul(v, bw/2))),
    add(c, add(mul(u,-bw/2), mul(v, bw/2)))
  ];
  tri(B[0],B[1],ap,col); tri(B[1],B[2],ap,col);
  tri(B[2],B[3],ap,col); tri(B[3],B[0],ap,col);
}

// flat ring in plane spanned by u,v
function ringP(c, r, n, u, v, col, sw, op){
  var pts = [], i;
  for(i = 0; i < n; i++){
    var a = i/n*Math.PI*2;
    pts.push(add(c, add(mul(u, Math.cos(a)*r), mul(v, Math.sin(a)*r))));
  }
  poly(pts, col, sw, op, 'none', 2);
}

function fistBox(h, e, s, col){
  var d = nrm(sub(h, e));
  var u = nrm(cross(d, Math.abs(d[1]) > 0.93 ? [1,0,0] : [0,1,0]));
  var v = nrm(cross(u, d));
  boxCC3(h, u, v, d, s, s, s, col);
}

// ============================================================
// 03 // ARENA : hexagon tiles, boundary, pylons, emblem
// ============================================================
var HEX = [], HEXI = [], PYL = [], BPOLY = [];

function buildArena(){
  var s = 1.1, q, r, i, a, x, z;
  for(q = -6; q <= 6; q++){
    for(r = -6; r <= 6; r++){
      x = 1.5*s*q;
      z = Math.sqrt(3)*s*(r + q/2);
      if(Math.hypot(x, z) < ARENA_R + 0.4){
        var o = [];
        for(i = 0; i < 6; i++){
          a = Math.PI/3*i;
          o.push([x + Math.cos(a)*s, 0, z + Math.sin(a)*s]);
        }
        HEX.push(o);
        if(((q + r) % 3 + 3) % 3 === 0){
          var oi = [];
          for(i = 0; i < 6; i++){
            a = Math.PI/3*i;
            oi.push([x + Math.cos(a)*s*0.55, 0, z + Math.sin(a)*s*0.55]);
          }
          HEXI.push(oi);
        }
      }
    }
  }
  for(i = 0; i < 6; i++){
    a = Math.PI/3*i + Math.PI/6;
    var px = Math.cos(a)*(ARENA_R + 0.32);
    var pz = Math.sin(a)*(ARENA_R + 0.32);
    PYL.push([px, 0, pz]);
    BPOLY.push([px, 0, pz]);
  }
}

function hexPts(cx, cz, r, rot){
  var p = [], i;
  for(i = 0; i < 6; i++){
    var a = Math.PI/3*i + (rot || 0);
    p.push([cx + Math.cos(a)*r, 0, cz + Math.sin(a)*r]);
  }
  return p;
}

function drawArena(){
  var i, j, a;
  for(i = 0; i < HEX.length; i++){ poly(HEX[i], '#0f5c2b', 1.1, 0.75, '#000', 0); }
  if(!FPS.low){
    for(i = 0; i < HEXI.length; i++){ poly(HEXI[i], '#0c3f1f', 0.8, 0.5, 'none', 0); }
  }
  poly(BPOLY, '#39ff6e', 2.5, 0.9, 'none', 0);
  var o = [];
  for(i = 0; i < 30; i++){
    a = i/30*Math.PI*2;
    o.push([Math.cos(a)*(ARENA_R + 1.1), 0, Math.sin(a)*(ARENA_R + 1.1)]);
  }
  poly(o, '#1f7a3d', 1.2, 0.5, 'none', 0);
  if(!FPS.low){
    var b = [];
    for(i = 0; i < 32; i++){
      a = i/32*Math.PI*2;
      b.push([Math.cos(a)*16, 0, Math.sin(a)*16]);
    }
    poly(b, '#0c3f1f', 1, 0.4, 'none', 0);
    for(i = 0; i < 12; i++){
      a = i/12*Math.PI*2 + 0.13;
      var x = Math.cos(a)*14, z = Math.sin(a)*14;
      lineSeg([x,0,z], [x,4.2,z], '#0f5c2b', 1.5, 0.5, 0);
    }
  }
  poly(hexPts(0,0,1.35,Math.PI/6), '#1f7a3d', 1.4, 0.8, 'none', 0);
  poly(hexPts(0,0,0.8,0), '#1f7a3d', 1.2, 0.8, 'none', 0);
  poly(hexPts(0,0,0.35,Math.PI/6), '#39ff6e', 1.2, 0.9, 'none', 0);
  for(i = 0; i < 3; i++){
    a = Math.PI/3*i + Math.PI/6;
    lineSeg([Math.cos(a)*0.8,0,Math.sin(a)*0.8],
            [Math.cos(a)*1.35,0,Math.sin(a)*1.35], '#1f7a3d', 1, 0.7, 0);
  }
  for(i = 0; i < 6; i++){
    lineSeg([0,0,0], [PYL[i][0],0,PYL[i][2]], '#0c3f1f', 0.8, 0.4, 0);
    var px = PYL[i][0], pz = PYL[i][2];
    boxCC3([px,1.4,pz], [1,0,0],[0,0,1],[0,1,0], 0.34, 0.34, 2.8, '#39ff6e');
    boxCC3([px,2.95,pz], [1,0,0],[0,0,1],[0,1,0], 0.52, 0.52, 0.26, '#39ff6e');
    lineSeg([px,3.1,pz], [px,4.0,pz], '#39ff6e', 2, 0.7, 0);
  }
  // SP ready pulse ring under fighters
  if(PL && GAME.state === 'fight' && PL.me >= 35){
    var rr = 0.55 + Math.sin(T*7)*0.12;
    poly(hexPts(PL.x, PL.z, rr, Math.PI/6 + T), '#b6ffd0', 1.6, 0.55, 'none', 0);
  }
  if(EN && GAME.state === 'fight' && EN.me >= 35){
    var rr2 = 0.55 + Math.sin(T*7 + 2)*0.12;
    poly(hexPts(EN.x, EN.z, rr2, Math.PI/6 + T), EN.R.col, 1.6, 0.55, 'none', 0);
  }
}

// ============================================================
// 04 // RIGS : humanoid proportions + enemy identity edits
// ============================================================
function baseRig(){
  return {
    scale: 1,
    chestW: 1.30, chestD: 0.66,
    abdW: 0.80, abdD: 0.55,
    pelW: 0.92, pelH: 0.46, pelD: 0.56,
    headW: 0.40, headH: 0.46, headD: 0.44,
    shX: 0.68, shY: 2.06,
    elX: 0.78, elY: 1.58, elZ: 0.12,
    haX: 0.58, haY: 1.18, haZ: 0.34,
    ua: 0.30, la: 0.25, fistW: 0.30,
    hipY: 0.98, hpX: 0.26,
    knX: 0.28, knY: 0.50, knZ: 0.03,
    th1: 0.40, th2: 0.30, ca1: 0.28, ca2: 0.18,
    ftX: 0.30, footW: 0.32, footD: 0.60,
    padW: 0.46,
    hunch: 0, hover: 0, jaw: 0,
    spikes: 0, gear: 0, crest: 0, pauldron: 0, slab: 0, horns: 0,
    halo: 0, wings: 0, ant: 0, spine: 0, fangs: 0, claws: 0,
    tail: 0, blade: 0, thruster: 0,
    hurtR: 0.19,
    name: 'VANGUARD-01', col: '#39ff6e', ai: 'player',
    hp: 100, dmgMul: 1, speed: 4.3, pref: 1.8, reach: 2.2, cool: 0.9
  };
}

var ROSTER = [
  { name:'GEAROX', col:'#ffd23f', hp:120, dmg:1.15, spd:0.74, pref:2.0, reach:2.3, cool:1.15, ai:'brute', scale:1.14,
    edit:function(R){
      R.chestW *= 1.35; R.ua *= 1.4; R.la *= 1.3; R.fistW *= 1.5;
      R.headW *= 0.85; R.headH *= 0.85; R.padW *= 1.25;
      R.th1 *= 1.3; R.th2 *= 1.25; R.hurtR *= 1.15;
      R.spikes = 1; R.gear = 1;
    }},
  { name:'VERMIL', col:'#ff4444', hp:100, dmg:1.0, spd:1.07, pref:1.85, reach:2.35, cool:0.7, ai:'blade', scale:1.03,
    edit:function(R){
      R.chestW *= 0.88; R.abdW *= 0.85; R.la = 0.17;
      R.shX *= 1.12; R.headW *= 0.9;
      R.blade = 1; R.crest = 1;
    }},
  { name:'KOLOSS', col:'#4fc3ff', hp:140, dmg:1.2, spd:0.65, pref:2.15, reach:2.35, cool:1.3, ai:'tank', scale:1.10,
    edit:function(R){
      R.chestW *= 1.28; R.shX *= 1.3; R.padW *= 1.5;
      R.pelW *= 1.2; R.th1 *= 1.35; R.th2 *= 1.3; R.ca1 *= 1.25;
      R.ua *= 1.3; R.fistW *= 1.15; R.hurtR *= 1.2;
      R.pauldron = 1; R.slab = 1; R.horns = 1;
    }},
  { name:'GHOST-9', col:'#e8f6ff', hp:90, dmg:0.9, spd:1.19, pref:2.0, reach:2.1, cool:0.7, ai:'ghost', scale:0.98,
    edit:function(R){
      R.chestW *= 0.75; R.chestD *= 0.85; R.abdW *= 0.75;
      R.ua *= 0.72; R.la *= 0.65; R.fistW *= 0.8;
      R.th1 *= 0.68; R.th2 *= 0.62; R.ca1 *= 0.62; R.ca2 *= 0.55;
      R.headW *= 1.2; R.headH *= 1.2;
      R.hover = 0.55; R.hurtR *= 0.85;
      R.halo = 1; R.wings = 1; R.ant = 1;
    }},
  { name:'EMBERFANG', col:'#ff9a3d', hp:110, dmg:1.05, spd:1.05, pref:1.65, reach:2.2, cool:0.8, ai:'beast', scale:1.06,
    edit:function(R){
      R.hunch = 1; R.chestW *= 1.12;
      R.headW *= 0.95; R.headH *= 0.8;
      R.fistW *= 1.1; R.ftX *= 1.15;
      R.jaw = 1; R.spine = 1; R.fangs = 1; R.claws = 1; R.tail = 1;
    }}
];

// all six selectable fighters (select indices)
var FULLROSTER = [{ name: 'VANGUARD-01', col: '#39ff6e' }].concat(
  ROSTER.map(function(r){ return { name: r.name, col: r.col }; })
);
var FULLSTAT = [{ hp: 100, dmg: 1.0, spd: 1.0 }].concat(
  ROSTER.map(function(r){ return { hp: r.hp, dmg: r.dmg, spd: r.spd }; })
);

// per character special move slots : [SP1 (RT), SP2 (LT)]
var CHARSPEC = {
  'VANGUARD-01': ['sp1', 'sp2'],
  'GEAROX':      ['g_slam', 'g_rush'],
  'VERMIL':      ['v_dance', 'v_cross'],
  'KOLOSS':      ['k_stomp', 'k_wall'],
  'GHOST-9':     ['gh_blast', 'gh_blink'],
  'EMBERFANG':   ['e_pounce', 'e_burst']
};

var SCALED = ['chestW','chestD','abdW','abdD','pelW','pelH','pelD',
  'headW','headH','headD','shX','shY','elX','elY','elZ','haX','haY','haZ',
  'ua','la','fistW','hipY','hpX','knX','knY','knZ','th1','th2','ca1','ca2',
  'ftX','footW','footD','padW','hurtR'];

function buildRig(name){
  var R = baseRig();
  if(name !== 'PLAYER'){
    var i, D;
    for(i = 0; i < ROSTER.length; i++){ if(ROSTER[i].name === name){ D = ROSTER[i]; } }
    for(var k = 0; k < SCALED.length; k++){ R[SCALED[k]] *= D.scale; }
    D.edit(R);
    R.name = D.name; R.col = D.col; R.ai = D.ai;
    R.hp = D.hp; R.dmgMul = D.dmg;
    R.speed = 4.3 * D.spd;
    R.pref = D.pref; R.reach = D.reach; R.cool = D.cool;
  }
  R.thruster = (name === 'PLAYER') ? 1 : 0;
  R.uchY = R.hipY + (R.shY - R.hipY)*0.94;
  R.chY = R.hipY + (R.shY - R.hipY)*0.60;
  return R;
}

// FULLROSTER index -> buildRig() key (index 0, VANGUARD-01, is the
// 'PLAYER' rig; everything else maps straight to its roster name)
function buildRigFor(selIdx){
  return buildRig(selIdx === 0 ? 'PLAYER' : FULLROSTER[selIdx].name);
}

// ============================================================
// 05 // POSE SYSTEM
// ============================================================
function basePose(f){
  var R = f.R;
  var br = Math.sin(T*3.0 + f.phase)*0.02;
  var p = {
    pel: [0, R.hipY, 0],
    chs: [0, R.chY + br, 0.02 + R.hunch*0.26],
    uch: [0, R.uchY + br*0.7, 0.03 + R.hunch*0.30],
    hed: [0, R.shY + 0.36 + R.hunch*(-0.10), 0.05 + R.hunch*0.42],
    shL: [-R.shX, R.shY, R.hunch*0.30],
    shR: [ R.shX, R.shY, R.hunch*0.30],
    elL: [-R.elX, R.elY, R.elZ + R.hunch*0.22],
    elR: [ R.elX, R.elY, R.elZ + R.hunch*0.22],
    haL: [-R.haX, R.haY, R.haZ + R.hunch*0.18],
    haR: [ R.haX, R.haY, R.haZ + R.hunch*0.18],
    hpL: [-R.hpX, R.hipY - 0.06, 0],
    hpR: [ R.hpX, R.hipY - 0.06, 0],
    knL: [-R.knX, R.knY, R.knZ],
    knR: [ R.knX, R.knY, R.knZ],
    ftL: [-R.ftX, 0.10, 0.06],
    ftR: [ R.ftX, 0.10, 0.06]
  };
  if(R.hover){
    var hs = Math.sin(T*2.8 + f.phase);
    p.pel[1] += R.hover;
    p.chs[1] += R.hover*0.9;
    p.uch[1] += R.hover*0.9;
    p.hed[1] += R.hover*0.8;
    p.knL[1] += R.hover*0.75 + hs*0.05;
    p.knR[1] += R.hover*0.75 - hs*0.05;
    p.ftL = [-R.ftX, R.hover*0.45 + hs*0.08, 0.14];
    p.ftR = [ R.ftX, R.hover*0.45 - hs*0.08, 0.14];
  }
  return p;
}

function walkPose(f){
  var R = f.R;
  var p = basePose(f);
  var sp = Math.hypot(f.mv[0], f.mv[1]);
  var a = 0.45 * Math.min(1, sp);
  var sw = Math.sin(f.walkPh), cw = Math.cos(f.walkPh);
  p.ftL = [-R.ftX, 0.10 + Math.max(0,cw)*0.36*a, 0.06 + sw*a];
  p.knL = [-R.knX, R.knY + Math.max(0,cw)*0.18*a, R.knZ + sw*a*0.5];
  p.ftR = [ R.ftX, 0.10 + Math.max(0,-cw)*0.36*a, 0.06 - sw*a];
  p.knR = [ R.knX, R.knY + Math.max(0,-cw)*0.18*a, R.knZ - sw*a*0.5];
  p.pel[1] += Math.abs(sw)*0.03 - 0.02;
  p.haL[2] = R.haZ - sw*0.14;
  p.haR[2] = R.haZ + sw*0.14;
  return p;
}

// ============================================================
// 06 // MOVE LIBRARY
//  Every state and move used by the FSM exists here. (FIX C1)
//  wins: hit windows. ev: timed events. dash: [t0,t1,speed].
//  yArc: hop height. armor: damage reduction window.
//  cost: SP meter price (specials only).
// ============================================================
function ringFX(c, col){ RINGS.push({ c: c, r: 0.3, l: 0.6, col: col }); }

function clampPos(f){
  var rr = Math.hypot(f.x, f.z);
  if(rr > ARENA_R - 0.55){
    var s = (ARENA_R - 0.55)/rr;
    f.x *= s; f.z *= s;
  }
}

function radialHit(f, foe, dmg, r, kb){
  var d = Math.hypot(foe.x - f.x, foe.z - f.z);
  if(d < r && foe.state !== 'ko'){
    applyHit(f, foe, { dmg: dmg, kb: kb, tip: null });
  }
}

function spawnOrb(f, foe, opt){
  var ang = opt.spread || 0;
  var dir = nrm([foe.x - f.x, 0, foe.z - f.z]);
  var ca = Math.cos(ang), sa = Math.sin(ang);
  var dx = dir[0]*ca - dir[2]*sa;
  var dz = dir[0]*sa + dir[2]*ca;
  PROJ.push({
    p: [f.x + dx*0.6, opt.y || 1.5, f.z + dz*0.6],
    v: [dx*(opt.v||11), 0, dz*(opt.v||11)],
    r: opt.r || 0.22, col: opt.col, life: opt.life || 1.1,
    dmg: opt.dmg, own: f, kind: opt.kind || 'orb', seed: Math.random()*7
  });
}

