        var e2 = EO((t-0.24)/0.10);
        var e3 = t > 0.5 ? 1 - EZ((t-0.5)/0.5) : 1;
        p.haR = [0.55*e2*e3, R.chY + 0.55*e2*e3, 0.35];
        p.haL = [-0.55*e2*e3, R.chY + 0.10, 0.35];
        p.elR = [0.60*e2*e3, R.chY + 0.20*e2*e3, 0.30];
      }
    }},

  // ---- KOLOSS specials ----
  k_stomp: { d: 0.85, name: 'SEISMIC STOMP', cost: 35,
    wins: [{ a0: 0.38, a1: 0.52, tip: 'ftR', dmg: 10, kb: 0.8 }],
    ev: [{ t: 0.46, fn: function(f,foe){
      spawnOrb(f, foe, { v: 9, y: 0.25, r: 0.34, dmg: 14, life: 0.9,
                         col: f.R.col, kind: 'crack' });
      SHAKE = Math.max(SHAKE, 0.30);
      snd('boom');
    }}],
    fn: function(f,t,p){
      var R = f.R, e1, e2;
      if(t < 0.38){
        e1 = EO(t/0.30);
        p.knR[1] += 0.55*e1; p.ftR[1] += 0.85*e1;
        p.hpR[2] -= 0.10*e1;
        p.haL[2] += 0.35*e1; p.haR[2] -= 0.30*e1;
        p.pel[1] += 0.05*e1;
      } else {
        e2 = EO((t-0.38)/0.10);
        p.knR[1] += 0.55*(1-e2); p.ftR[1] = 0.10;
        p.ftR[2] = L(0.06, 0.85, e2);
        p.pel[1] -= 0.16*e2;
        p.knL[1] -= 0.14*e2; p.knL[2] += 0.12*e2;
        p.chs[2] += 0.14*e2;
      }
    }},
  k_wall: { d: 1.25, name: 'IRON WALL', dash: [0.15, 0.95, 3.4], armor: [0.15, 0.95], cost: 55,
    wins: [{ a0: 0.16, a1: 0.92, tip: 'shR', dmg: 15, kb: 2.6 }],
    fn: function(f,t,p){
      var R = f.R;
      var e = EZ(Math.min(1, t/0.15));
      var eo = t > 0.95 ? 1 - EZ((t-0.95)/0.30) : 1;
      e *= eo;
      p.chs[2] += 0.22*e; p.uch[2] += 0.22*e; p.hed[2] += 0.16*e;
      p.haL = [L(R.haX, 0.16, e), L(R.haY, R.chY + 0.16, e), L(R.haZ, 0.52, e)];
      p.haR = [L(R.haX, -0.16, e), L(R.haY, R.chY - 0.08, e), L(R.haZ, 0.55, e)];
      p.elL = [-0.34, R.elY + 0.10, 0.34*e];
      p.elR = [ 0.34, R.elY + 0.04, 0.36*e];
      p.pel[1] -= 0.06*e;
      p.knL[2] += 0.08*e; p.knR[2] += 0.08*e;
    }},

  // ---- GHOST-9 specials ----
  gh_blast: { d: 0.62, name: 'PHASE BLAST', cost: 30,
    wins: [],
    ev: [{ t: 0.30, fn: function(f,foe){
      spawnOrb(f, foe, { v: 11, y: 1.5, r: 0.24, dmg: 12, life: 1.1,
                         col: '#ffffff', kind: 'orb' });
      snd('swoosh');
    }}],
    fn: function(f,t,p){
      var R = f.R, e = EO(Math.min(1, t/0.25));
      var rec = (t > 0.30 && t < 0.5) ? Math.sin((t-0.30)/0.20*Math.PI)*0.10 : 0;
      p.haL = [0.14, R.chY + 0.12, L(R.haZ, 0.85, e) - rec];
      p.haR = [-0.14, R.chY + 0.08, L(R.haZ, 0.85, e) - rec];
      p.elL = [-0.34, R.elY + 0.10, 0.45*e];
      p.elR = [ 0.34, R.elY + 0.06, 0.45*e];
      p.pel[1] += 0.08*e;
      p.knL[1] += 0.06*e; p.knR[1] += 0.06*e;
    }},
  gh_blink: { d: 0.60, name: 'BLINK STRIKE', cost: 45,
    wins: [{ a0: 0.28, a1: 0.42, tip: 'haR', dmg: 15, kb: 1.0 }],
    ev: [{ t: 0.20, fn: function(f,foe){
      f.x = foe.x + Math.sin(foe.yaw)*1.1;
      f.z = foe.z + Math.cos(foe.yaw)*1.1;
      f.yaw = Math.atan2(foe.x - f.x, foe.z - f.z);
      clampPos(f);
      spark([f.x, 1.4, f.z], '#ffffff', 8);
      snd('tele');
    }}],
    fn: function(f,t,p){
      var R = f.R;
      var e1 = EO(Math.min(1, t/0.18));
      var e2 = t < 0.26 ? 0 : EO((t-0.26)/0.08);
      var e3 = t > 0.55 ? 1 - EZ((t-0.55)/0.45) : 1;
      if(t < 0.26){
        p.haL = [-0.12, R.chY + 0.15, 0.40*e1];
        p.haR = [ 0.12, R.chY - 0.05, 0.42*e1];
      } else {
        p.haR = [L(0.12, -0.62, e2*e3), R.chY + 0.10, 0.85*e2*e3];
        p.elR = [L(0.30, -0.45, e2*e3), R.chY + 0.10, 0.55*e2*e3];
      }
    }},

  // ---- EMBERFANG specials ----
  e_pounce: { d: 0.70, name: 'FANG RUSH', dash: [0.15, 0.50, 7.5], yArc: 1.2, cost: 40,
    wins: [{ a0: 0.42, a1: 0.60, tip: 'hed', dmg: 16, kb: 1.4 }],
    fn: function(f,t,p){
      var R = f.R, e1, e2;
      if(t < 0.15){
        e1 = EO(t/0.15);
        p.pel[1] -= 0.30*e1;
        p.knL[1] -= 0.24*e1; p.knR[1] -= 0.24*e1;
        p.knL[2] += 0.20*e1; p.knR[2] += 0.20*e1;
        p.hed[2] += 0.15*e1;
      } else {
        e2 = EO((t-0.15)/0.15);
        p.chs[2] += 0.42*e2; p.uch[2] += 0.42*e2; p.hed[2] += 0.55*e2;
        p.pel[2] += 0.20*e2;
        p.haL = [-0.35, R.chY + 0.15, R.haZ + 0.75*e2];
        p.haR = [ 0.35, R.chY + 0.15, R.haZ + 0.75*e2];
        p.knL[2] -= 0.25*e2; p.knR[2] -= 0.25*e2;
      }
    }},
  e_burst: { d: 0.80, name: 'EMBER BURST', cost: 50,
    wins: [],
    ev: [
      { t: 0.30, fn: function(f,foe){
        spawnOrb(f, foe, { v: 6, y: 1.3, r: 0.16, dmg: 4, life: 0.7, col: f.R.col, kind: 'spark' });
        spawnOrb(f, foe, { v: 6, y: 1.3, r: 0.16, dmg: 4, life: 0.7, col: f.R.col, kind: 'spark', spread: 0.35 });
        spawnOrb(f, foe, { v: 6, y: 1.3, r: 0.16, dmg: 4, life: 0.7, col: f.R.col, kind: 'spark', spread: -0.35 });
      }},
      { t: 0.45, fn: function(f,foe){
        spawnOrb(f, foe, { v: 6.5, y: 1.4, r: 0.16, dmg: 4, life: 0.7, col: f.R.col, kind: 'spark' });
        spawnOrb(f, foe, { v: 6.5, y: 1.4, r: 0.16, dmg: 4, life: 0.7, col: f.R.col, kind: 'spark', spread: 0.3 });
        spawnOrb(f, foe, { v: 6.5, y: 1.4, r: 0.16, dmg: 4, life: 0.7, col: f.R.col, kind: 'spark', spread: -0.3 });
      }},
      { t: 0.60, fn: function(f,foe){
        spawnOrb(f, foe, { v: 7, y: 1.5, r: 0.16, dmg: 4, life: 0.7, col: f.R.col, kind: 'spark' });
        spawnOrb(f, foe, { v: 7, y: 1.5, r: 0.16, dmg: 4, life: 0.7, col: f.R.col, kind: 'spark', spread: 0.25 });
        spawnOrb(f, foe, { v: 7, y: 1.5, r: 0.16, dmg: 4, life: 0.7, col: f.R.col, kind: 'spark', spread: -0.25 });
        snd('swoosh');
      }}
    ],
    fn: function(f,t,p){
      var R = f.R;
      var e1 = EO(Math.min(1, t/0.22));
      var e2 = (t > 0.26 && t < 0.62) ? EO((t-0.26)/0.08) : (t >= 0.62 ? 1 - EZ((t-0.62)/0.18) : 0);
      p.hed[2] += 0.44*(e2 - e1);
      p.chs[2] += 0.10*(e2 - e1*0.5);
      p.haL = [-0.28, R.chY - 0.15, 0.35];
      p.haR = [ 0.28, R.chY - 0.18, 0.38];
      p.pel[1] -= 0.10*e1;
    }}
};

// ============================================================
// 07 // FIGHTER
// ============================================================
function Fighter(R, ctrl){
  this.R = R;
  this.ctrl = ctrl || 'cpu';        // 'p1' | 'p2' | 'cpu'
  this.x = 0; this.z = 0; this.y = 0; this.yaw = 0;
  this.phase = Math.random()*6;
  this.hp = R.hp; this.maxhp = R.hp;
  this.me = 25;
  this.state = 'idle';
  this.anim = null;
  this.t = 0;
  this.mv = [0,0];
  this.walkPh = 0;
  this.cool = 0.8;
  this.blockT = 0;
  this.blockHold = false;
  this.lastP = 'cross';
  this.wh = [];
  this.evI = 0;
  this.dk = [0,1];
  this.armor = 0;
  this.prevTips = null;
  this.combo = 0;
  this.comboT = 0;
  this.J = null;
  this.aiT = 0; this.aiS = 0;
}

Fighter.prototype.tryMove = function(name){
  var M = MOVE[name];
  if(!M || this.cool > 0 || GAME.state !== 'fight' || GAME.paused) return false;
  if(this.state !== 'idle' && this.state !== 'walk') return false;
  var cost = M.cost || 0;
  if(this.me < cost){
    setTxt(EL.mvn, 'LOW SP');
    MVT = 0.5;
    return false;
  }
  this.me -= cost;
  this.state = 'attack'; this.anim = name; this.t = 0;
  this.wh = []; this.evI = 0; this.y = 0;
  this.dk = [Math.sin(this.yaw), Math.cos(this.yaw)];
  this.cool = 0.2;
  if(M.name){
    setTxt(EL.mvn, (this.ctrl === 'p1' ? 'P1: ' : (this.ctrl === 'p2' ? 'P2: ' : 'CPU: ')) + M.name);
    MVT = 1.0;
  }
  if(cost){ snd('swoosh'); }
  return true;
};

Fighter.prototype.think = function(dt, foe){
  this.cool -= dt;
  this.armor = 0;
  if(this.comboT > 0){
    this.comboT -= dt;
    if(this.comboT <= 0){ this.combo = 0; }
  }
  switch(this.state){
    case 'intro':
      this.t += dt;
      if(this.t >= MOVE.intro.d){ this.state = 'idle'; this.anim = null; this.t = 0; }
      break;
    case 'hit':
      this.t += dt;
      if(this.t >= MOVE[this.anim].d){ this.state = 'idle'; this.anim = null; this.t = 0; }
      break;
    case 'ko':
      this.t += dt;
      if(this.t > MOVE.ko.d){ this.t = MOVE.ko.d; }
      break;
    case 'victory':
      this.t = (this.t + dt) % MOVE.victory.d;
      break;
    case 'block':
      this.t += dt;
      if(!this.blockHold){ this.state = 'idle'; this.t = 0; }
      break;
    case 'attack': {
      this.t += dt / MOVE[this.anim].d;
      var M = MOVE[this.anim];
      if(M.dash && this.t >= M.dash[0] && this.t <= M.dash[1]){
        this.x += this.dk[0]*M.dash[2]*dt;
        this.z += this.dk[1]*M.dash[2]*dt;
        clampPos(this);
      }
      this.y = M.yArc ? M.yArc * Math.sin(Math.PI * clamp(this.t, 0, 1)) : 0;
      if(M.armor && this.t >= M.armor[0] && this.t <= M.armor[1]){
        this.armor = 1;
      }
      var evs = M.ev || [];
      while(this.evI < evs.length && this.t >= evs[this.evI].t){
        evs[this.evI].fn(this, foe);
        this.evI++;
      }
      if(this.t >= 1){
        this.state = 'idle'; this.anim = null; this.t = 0; this.y = 0;
      }
      break;
    }
    case 'idle':
    case 'walk': {
      var ddx = foe.x - this.x, ddz = foe.z - this.z;
      if(ddx || ddz){ this.yaw = Math.atan2(ddx, ddz); }
      var sp = Math.hypot(this.mv[0], this.mv[1]);
      if(sp > 0.05){
        this.state = 'walk';
        var n = Math.max(1, sp);
        var ix = this.mv[0]/n, iy = this.mv[1]/n;
        this.x += (Math.sin(this.yaw)*iy + Math.cos(this.yaw)*ix) * this.R.speed * dt;
        this.z += (Math.cos(this.yaw)*iy - Math.sin(this.yaw)*ix) * this.R.speed * dt;
        this.walkPh += dt * (7.5 + 4*Math.min(1, sp));
      } else {
        this.state = 'idle';
      }
      clampPos(this);
      break;
    }
  }
  // FIX C2 : capture previous frame tip positions BEFORE re-pose,
  // so resolveAttacks gets a true swept segment.
  if(this.state === 'attack' && this.J){
    var M2 = MOVE[this.anim];
    if(M2){
      var tp = {}, i;
      for(i = 0; i < M2.wins.length; i++){
        tp[M2.wins[i].tip] = this.J[M2.wins[i].tip];
      }
      this.prevTips = tp;
    }
  } else {
    this.prevTips = null;
  }
  this.poseNow();
};

Fighter.prototype.poseNow = function(){
  var p, R = this.R;
  if(this.state === 'walk'){
    p = walkPose(this);
  } else if(this.state === 'idle'){
    p = basePose(this);
    p.haL[1] += Math.sin(T*3 + this.phase)*0.03;
    p.haR[1] -= Math.sin(T*3 + this.phase)*0.03;
    p.hed[1] += Math.sin(T*3 + this.phase)*0.02;
  } else if(this.state === 'block'){
    p = basePose(this);
    var e = EZ(Math.min(1, this.t*6));
    p.haL = [L(R.haX,-0.14,e), L(R.haY,R.chY+0.14,e), L(R.haZ,0.50*R.scale,e)];
    p.haR = [L(R.haX, 0.16,e), L(R.haY,R.chY-0.10,e), L(R.haZ,0.54*R.scale,e)];
    p.elL = [L(R.elX,-0.32,e), L(R.elY,R.elY+0.12,e), L(R.elZ,0.30,e)];
    p.elR = [L(R.elX, 0.34,e), L(R.elY,R.elY+0.05,e), L(R.elZ,0.32,e)];
    p.pel[1] -= 0.06*e;
    p.knL[2] += 0.08*e; p.knR[2] += 0.08*e;
  } else if(this.state === 'intro'){
    p = basePose(this);
    MOVE.intro.fn(this, this.t, p);
  } else if(this.state === 'attack' || this.state === 'hit'){
    p = basePose(this);
    var M = MOVE[this.anim];
    if(M && M.fn){ M.fn(this, this.t, p); }
  } else if(this.state === 'ko'){
    p = basePose(this);
    MOVE.ko.fn(this, this.t, p);
  } else if(this.state === 'victory'){
    p = basePose(this);
    MOVE.victory.fn(this, this.t, p);
  } else {
    p = basePose(this);
  }
  // local -> world : yaw rotation + fighter offset
  var cy = Math.cos(this.yaw), sy = Math.sin(this.yaw), J = {}, k;
  for(k in p){
    var q = p[k];
    J[k] = [this.x + q[0]*cy + q[2]*sy, this.y + q[1], this.z - q[0]*sy + q[2]*cy];
  }
  this.J = J;
};

// ============================================================
// 08 // COMBAT RESOLUTION
// ============================================================
function label(f){ return f.ctrl === 'p1' ? 'P1' : (f.ctrl === 'p2' ? 'P2' : 'CPU'); }

function resolveAttacks(){
  tryHit(PL, EN);
  tryHit(EN, PL);
}

function tryHit(f, foe){
  if(!f || !foe || f.state !== 'attack' || !f.J || foe.state === 'ko') return;
  var M = MOVE[f.anim];
  if(!M || !M.wins || !M.wins.length) return;
  // attacker must roughly face the defender
  var dirx = foe.x - f.x, dirz = foe.z - f.z;
  var dl = Math.hypot(dirx, dirz) || 1;
  if((dirx * Math.sin(f.yaw) + dirz * Math.cos(f.yaw)) / dl < -0.15) return;
  var i, w;
  for(i = 0; i < M.wins.length; i++){
    w = M.wins[i];
    if(f.wh[i]) continue;
    if(f.t > w.a1){ f.wh[i] = 1; continue; }
    if(f.t < w.a0) continue;
    var tip = f.J[w.tip];
    if(!tip){ f.wh[i] = 1; continue; }
    var prev = f.prevTips ? f.prevTips[w.tip] : null;
    var lo = [foe.x, 0.12 + foe.y, foe.z];
    var hi = [foe.x, foe.R.shY * 0.95 + foe.y, foe.z];
    var dist = prev ? segSeg(prev, tip, lo, hi) : segSeg(tip, tip, lo, hi);
    if(dist < foe.R.hurtR + 0.34){
      f.wh[i] = 1;
      applyHit(f, foe, w, tip);
    }
  }
}

function applyHit(att, def, w, tip){
  if(GAME.state !== 'fight' || GAME.paused || def.state === 'ko') return;
  var hp = tip || [def.x, def.R.chY, def.z];
  var blocked = false;
  if(def.state === 'block'){
    var bx = att.x - def.x, bz = att.z - def.z;
    var bl = Math.hypot(bx, bz) || 1;
    if((bx * Math.sin(def.yaw) + bz * Math.cos(def.yaw)) / bl > 0.2) blocked = true;
  }
  var dmg = w.dmg * att.R.dmgMul;
  if(def.armor) dmg *= 0.3;
  if(blocked) dmg *= 0.16;
  def.hp = Math.max(0, def.hp - dmg);
  att.me = Math.min(100, att.me + dmg * 0.5);
  def.me = Math.min(100, def.me + dmg * 0.35 + (blocked ? 3 : 0));
  // knockback
  var kx = def.x - att.x, kz = def.z - att.z;
  var kl = Math.hypot(kx, kz) || 1;
  var kb = (w.kb || 0.5) * (blocked ? 0.25 : 1);
  def.x += kx / kl * kb * 0.5;
  def.z += kz / kl * kb * 0.5;
  clampPos(def);
  spark(hp, blocked ? '#b6ffd0' : def.R.col, blocked ? 4 : 7);
  if(blocked){
    SHAKE = Math.max(SHAKE, 0.07);
    snd('block');
    return;
  }
  att.combo++;
  att.comboT = 1.1;
  SHAKE = Math.max(SHAKE, 0.14 + dmg * 0.008);
  FLASH = Math.max(FLASH, 0.22);
  snd('hit');
  if(def.ctrl === 'p1'){ rumble(0, 90, 0.5); }
  else if(def.ctrl === 'p2'){ rumble(1, 90, 0.5); }
  if(def.hp <= 0){ doKO(def, att); return; }
  if(def.armor){ return; }   // armored attacks are not interrupted
  def.state = 'hit';
  def.anim = (w.kb > 1.05 || w.dmg >= 12) ? 'hitgut' : 'hithigh';
  def.t = 0;
  def.y = 0;
  def.blockHold = false;
  def.cool = 0.15;
}

function doKO(def, att){
  GAME.state = 'end';
  GAME.koT = 0;
  def.state = 'ko'; def.anim = 'ko'; def.t = 0; def.y = 0;
  def.mv = [0,0]; def.blockHold = false;
  att.state = 'victory'; att.anim = 'victory'; att.t = 0; att.mv = [0,0];
  if(def === PL){ GAME.enw++; } else { GAME.plw++; }
  banner('K.O.', label(att) + ' TAKES THE ROUND', 2.2);
  snd('ko');
  SHAKE = 0.6; FLASH = 0.85;
  spark([def.x, def.R.chY, def.z], def.R.col, 16);
  ringFX([def.x, 0.1, def.z], def.R.col);
  rumble(0, 300, 0.9);
  rumble(1, 300, 0.9);
}

function timeUp(){
  GAME.timer = 0;
  GAME.state = 'end';
  GAME.koT = 0;
  var w = null;
  if(PL.hp > EN.hp + 0.01){ w = PL; }
  else if(EN.hp > PL.hp + 0.01){ w = EN; }
  if(w){
    if(w === PL){ GAME.plw++; } else { GAME.enw++; }
    w.state = 'victory'; w.anim = 'victory'; w.t = 0; w.mv = [0,0];
    banner('TIME UP', label(w) + ' TAKES THE ROUND', 2.2);
  } else {
    banner('TIME UP', 'DRAW ROUND', 2.2);
  }
  snd('bell');
}

function separation(){
  if(!PL || !EN) return;
  var dx = EN.x - PL.x, dz = EN.z - PL.z;
  var d = Math.hypot(dx, dz);
  if(d < 1.05 && d > 1e-4){
    var push = (1.05 - d) / 2;
    var nx = dx / d, nz = dz / d;
    PL.x -= nx * push; PL.z -= nz * push;
    EN.x += nx * push; EN.z += nz * push;
    clampPos(PL); clampPos(EN);
  }
}

// ============================================================
// 09 // AI (campaign opponents)
// ============================================================
var AIP = {
  brute: { block: 0.08, strafe: 0.25 },
  blade: { block: 0.30, strafe: 0.80 },
  tank:  { block: 0.45, strafe: 0.08 },
  ghost: { block: 0.22, strafe: 1.00 },
  beast: { block: 0.04, strafe: 0.45 }
};
var SPRANGE = {
  sp1: [0, 3.2], sp2: [0, 2.6],
  g_slam: [0, 2.5], g_rush: [2.0, 9], v_dance: [0, 2.4], v_cross: [1.6, 9],
  k_stomp: [0, 3.2], k_wall: [1.4, 9], gh_blast: [1.6, 9], gh_blink: [0, 2.0],
  e_pounce: [1.5, 9], e_burst: [1.2, 6]
};
var AIGAP = { brute: 'g_rush', blade: 'v_cross', tank: 'k_wall', ghost: 'gh_blink', beast: 'e_pounce' };

function aiThink(f, foe, dt){
  f.mv = [0, 0];
  f.blockHold = false;
  if(f.state !== 'idle' && f.state !== 'walk') return;
  if(foe.state === 'ko') return;
  var dx = foe.x - f.x, dz = foe.z - f.z;
  var d = Math.hypot(dx, dz) || 0.001;
  var P = AIP[f.R.ai] || AIP.brute;
  f.aiT -= dt;
  if(f.aiT <= 0){
    f.aiT = rnd(0.35, 0.9);
    f.aiS = Math.random() < P.strafe ? (Math.random() < 0.5 ? -1 : 1) : 0;
  }
  if(d > f.R.pref + 0.45){ f.mv[1] = 1; }
  else if(d < f.R.pref - 0.55){ f.mv[1] = -1; }
  if(f.mv[1] === 0 || Math.random() < 0.6){ f.mv[0] = f.aiS; }
  if(f.blockT > 0){
    f.blockT -= dt;
    f.blockHold = true;
    return;
  }
  if(foe.state === 'attack' && d < 3.0 && Math.random() < P.block * 1.6){
    f.blockT = rnd(0.25, 0.55);
    f.blockHold = true;
    return;
  }
  var spec = CHARSPEC[f.R.name] || ['sp1', 'sp2'];
  // gap closer
  if(f.cool <= 0 && d > f.R.pref + 0.7){
    var gn = AIGAP[f.R.ai];
    if(gn && f.me >= (MOVE[gn].cost || 0) && Math.random() < dt * 1.4){
      if(f.tryMove(gn)){ f.cool = rnd(0.5, 1.0) * f.R.cool; return; }
    }
  }
  // ghost keeps distance with projectiles
  if(f.cool <= 0 && d > 2.4 && f.R.ai === 'ghost' && f.me >= 30 && Math.random() < dt * 1.6){
    if(f.tryMove('gh_blast')){ f.cool = rnd(0.5, 0.9) * f.R.cool; return; }
  }
  // melee pressure
  if(f.cool <= 0 && d < f.R.reach + 0.2){
    var did = false;
    if(f.me >= 38 && Math.random() < 0.5){
      var cand = [], k;
      for(k = 0; k < spec.length; k++){
        var rg = SPRANGE[spec[k]];
        if(rg && d >= rg[0] && d <= rg[1] && f.me >= (MOVE[spec[k]].cost || 0)){
          cand.push(spec[k]);
        }
      }
      if(cand.length){ did = f.tryMove(cand[(Math.random() * cand.length) | 0]); }
    }
    if(!did){
      var rr = Math.random();
      var nm = rr < 0.34 ? 'jab' : (rr < 0.62 ? 'cross' : (rr < 0.88 ? 'kick' : 'jumpatk'));
      did = f.tryMove(nm);
    }
    if(did){ f.cool = rnd(0.45, 0.95) * f.R.cool; }
  }
}

// ============================================================
// 10 // FX + PROJECTILES
// ============================================================
function spark(p, col, n){
  if(FPS.low){ n = Math.ceil(n / 2); }
  for(var i = 0; i < n; i++){
    SPARKS.push({ p: p.slice(), v: [rnd(-4,4), rnd(1.5,6), rnd(-4,4)],
                  l: rnd(0.25, 0.55), col: col });
  }
  if(SPARKS.length > 90){ SPARKS.splice(0, SPARKS.length - 90); }
}

function updFX(dt){
  var i;
  for(i = SPARKS.length - 1; i >= 0; i--){
    var s = SPARKS[i];
    s.p[0] += s.v[0]*dt; s.p[1] += s.v[1]*dt; s.p[2] += s.v[2]*dt;
    s.v[1] -= 9.5*dt;
    if(s.p[1] < 0.03){ s.p[1] = 0.03; s.v[1] *= -0.4; s.v[0] *= 0.7; s.v[2] *= 0.7; }
    s.l -= dt;
    if(s.l <= 0){ SPARKS.splice(i, 1); }
  }
  for(i = RINGS.length - 1; i >= 0; i--){
    var r = RINGS[i];
    r.r += 6.5*dt; r.l -= dt;
    if(r.l <= 0){ RINGS.splice(i, 1); }
  }
}

function updProj(dt){
  var i;
  for(i = PROJ.length - 1; i >= 0; i--){
    var p = PROJ[i];
    p.p[0] += p.v[0]*dt; p.p[1] += p.v[1]*dt; p.p[2] += p.v[2]*dt;
    p.life -= dt;
    var foe = (p.own === PL) ? EN : PL;
    var hit = false;
    if(foe && foe.state !== 'ko' && GAME.state === 'fight' && !GAME.paused){
      var lo = [foe.x, 0.12 + foe.y, foe.z];
      var hi = [foe.x, foe.R.shY * 0.95 + foe.y, foe.z];
      var dd = segSeg(p.p, p.p, lo, hi);
      if(dd < p.r + foe.R.hurtR + 0.3){
        applyHit(p.own, foe, { dmg: p.dmg, kb: 0.7 }, p.p.slice());
        spark(p.p, p.col, 6);
        hit = true;
      }
    }
    if(hit || p.life <= 0 || Math.hypot(p.p[0], p.p[2]) > ARENA_R + 2.6){
      PROJ.splice(i, 1);
    }
  }
}

function drawProj(p){
  if(p.kind === 'crack'){
    poly(hexPts(p.p[0], p.p[2], 0.3 + 0.1*Math.sin(T*25 + p.seed), T*9), p.col, 2, 0.9, 'none', 0);
    var i;
    for(i = 0; i < 3; i++){
      var a = p.seed + i * 2.1;
      var bx = p.p[0] + Math.cos(a)*0.25, bz = p.p[2] + Math.sin(a)*0.25;
      lineSeg([bx, 0.02, bz], [bx, 0.3 + 0.12*Math.sin(T*20 + i), bz], p.col, 1.8, 0.9, 1);
    }
  } else if(p.kind === 'spark'){
    lineSeg(p.p, [p.p[0]-p.v[0]*0.06, p.p[1], p.p[2]-p.v[2]*0.06], p.col, 2.4, 0.95, 2);
    ringP(p.p, p.r, 6, [1,0,0], [0,1,0], p.col, 1.4, 0.8);
  } else {
    var wob = T*6 + p.seed;
    ringP(p.p, p.r*(1.1 + 0.15*Math.sin(T*14 + p.seed)), 10,
          [Math.cos(wob), 0, Math.sin(wob)], [0,1,0], p.col, 2, 0.95);
    ringP(p.p, p.r*1.05, 10, [1,0,0], [0,0,1], p.col, 1.4, 0.6);
    lineSeg([p.p[0]-p.v[0]*0.12, p.p[1], p.p[2]-p.v[2]*0.12], p.p, p.col, 1.6, 0.5, 2);
  }
}

function drawFX(){
  var i;
  for(i = 0; i < SPARKS.length; i++){
    var s = SPARKS[i];
    lineSeg(s.p, [s.p[0]-s.v[0]*0.03, s.p[1]-s.v[1]*0.03, s.p[2]-s.v[2]*0.03],
            s.col, 2.2, Math.min(1, s.l*2.4), 2);
  }
  for(i = 0; i < RINGS.length; i++){
    var r = RINGS[i];
    poly(hexPts(r.c[0], r.c[2], r.r, T*2.5), r.col, 2.5,
         Math.max(0, Math.min(0.9, r.l*1.6)), 'none', 1);
  }
  for(i = 0; i < PROJ.length; i++){ drawProj(PROJ[i]); }
}

// ============================================================
// 11 // FIGHTER DRAW (black faced solids + identity kit)
// ============================================================
function drawFighter(f){
  if(!f || !f.J) return;
  var R = f.R, J = f.J, col = R.col, i, sgn;
  var cyw = Math.cos(f.yaw), syw = Math.sin(f.yaw);
  var FWD = [syw, 0, cyw], RGT = [cyw, 0, -syw], UP = [0,1,0];
  // ground shadow
  poly(hexPts(f.x, f.z, 0.55, f.yaw), '#0c3f1f', 1, 0.55, 'none', 0);
  // torso
  limbTaper(J.pel, J.chs, R.pelW*0.92, R.abdW, col);
  limbTaper(J.chs, J.uch, R.abdW*0.96, R.chestW*0.8, col);
  boxCC3(mid(J.chs, J.uch, 0.55), RGT, UP, FWD, R.chestW*0.98,
         (R.uchY - R.chY)*1.15 + 0.16, R.chestD, col);
  boxCC3(J.pel, RGT, UP, FWD, R.pelW, R.pelH, R.pelD, col);
  // neck + head
  limbTaper(J.uch, mid(J.uch, J.hed, 0.75), 0.2, 0.17, col);
  boxCC3(J.hed, RGT, UP, FWD, R.headW, R.headH, R.headD, col);
  // visor
  var vzz = R.headD*0.52, vxx = R.headW*0.34;
  lineSeg(add(J.hed, add(mul(RGT, -vxx), mul(FWD, vzz))),
          add(J.hed, add(mul(RGT,  vxx), mul(FWD, vzz))), '#eafff2', 2.4, 0.95, 2);
  // identity kit
  if(R.jaw){
    var jm = add(J.hed, add(mul(FWD, R.headD*0.28), mul(UP, -R.headH*0.45)));
    boxCC3(jm, RGT, UP, FWD, R.headW*0.72, 0.15, R.headD*0.5, col);
    pyr(add(jm, mul(RGT, -R.headW*0.28)), mul(UP, -1), 0.16, 0.08, col);
    pyr(add(jm, mul(RGT,  R.headW*0.28)), mul(UP, -1), 0.16, 0.08, col);
  }
  if(R.horns){
    for(sgn = -1; sgn <= 1; sgn += 2){
      pyr(add(J.hed, add(mul(RGT, sgn*R.headW*0.44), mul(UP, R.headH*0.5))),
          nrm(add(mul(RGT, sgn*0.7), mul(UP, 1))), 0.34*R.scale, 0.13, col);
    }
  }
  if(R.crest){
    pyr(add(J.hed, mul(UP, R.headH*0.55)), nrm(add(mul(UP, 1), mul(FWD, 0.5))),
        0.44*R.scale, 0.15, col);
  }
  if(R.halo){
    var hc = add(J.hed, mul(UP, R.headH*0.5 + 0.4));
    var hu = [Math.cos(T*2.2), 0, Math.sin(T*2.2)];
    var hv = [-Math.sin(T*2.2), 0, Math.cos(T*2.2)];
    ringP(hc, 0.34, 16, hu, hv, '#e8f6ff', 1.8, 0.9);
  }
  if(R.ant){
    var at = add(J.hed, mul(UP, R.headH*0.55));
    lineSeg(at, add(at, mul(UP, 0.42)), '#e8f6ff', 1.6, 0.9, 2);
    ringP(add(at, mul(UP, 0.46)), 0.06, 6, [1,0,0], [0,1,0], '#e8f6ff', 1.4, 0.9);
  }
  if(R.wings){
    var fl = 0.75 + 0.35*Math.sin(T*3.5 + f.phase);
    for(sgn = -1; sgn <= 1; sgn += 2){
      var w0 = add(J.uch, mul(RGT, sgn*0.28));
      var w1 = add(w0, add(mul(RGT, sgn*0.85), mul(UP, 0.55*fl)));
      var w2 = add(w1, add(mul(RGT, sgn*0.55), mul(UP, 0.5*fl)));
      var w3 = add(w2, add(mul(RGT, sgn*0.18), mul(UP, -0.25)));
      pline([w0, w1, w2, w3], '#e8f6ff', 1.6, 0.55, 2);
      pline([w0, add(w1, mul(UP, 0.3)), add(w2, mul(UP, -0.1))], '#e8f6ff', 1.2, 0.4, 2);
    }
  }
  if(R.spikes){
    var shs = [J.shL, J.shR];
    for(i = 0; i < 2; i++){
      pyr(add(shs[i], mul(UP, R.padW*0.45)), mul(UP, 1), 0.3, 0.14, col);
    }
    for(i = 0; i < 3; i++){
      var sp = mid(J.pel, J.chs, 0.25 + i*0.3);
      pyr(add(sp, mul(FWD, -R.chestD*0.55)),
          nrm(add(mul(UP, 0.8), mul(FWD, -1))), 0.26, 0.12, col);
    }
  }
  if(R.gear){
    var gu = [Math.cos(T*3), 0, Math.sin(T*3)];
    var gv = [-Math.sin(T*3), 0, Math.cos(T*3)];
    ringP(J.pel, R.pelW*0.8, 12, gu, gv, col, 1.6, 0.85);
    for(i = 0; i < 6; i++){
      var a = T*3 + i/6*Math.PI*2;
      var tu = [Math.cos(a), 0, Math.sin(a)];
      lineSeg(add(J.pel, mul(tu, R.pelW*0.8)),
              add(J.pel, mul(tu, R.pelW*0.8 + 0.14)), col, 1.6, 0.85, 2);
    }
  }
  if(R.pauldron){
    var PS = [J.shL, J.shR];
    for(i = 0; i < 2; i++){
      boxCC3(PS[i], RGT, UP, FWD, R.padW*1.5, R.padW*0.95, R.padW*1.35, col);
      pyr(add(PS[i], mul(UP, R.padW*0.55)), mul(UP, 1), 0.3, 0.15, col);
    }
  } else {
    var PS2 = [J.shL, J.shR];
    for(i = 0; i < 2; i++){
      boxCC3(PS2[i], RGT, UP, FWD, R.padW, R.padW*0.55, R.padW*0.8, col);
    }
  }
  if(R.slab){
    boxCC3(add(mid(J.chs, J.uch, 0.5), mul(FWD, R.chestD*0.55)),
           RGT, UP, FWD, R.chestW*0.62, 0.5, 0.12, col);
  }
  if(R.spine){
    for(i = 0; i < 4; i++){
      var spq = mid(J.pel, J.chs, i/3);
      pyr(add(spq, mul(FWD, -R.pelD*0.5)),
          nrm(add(mul(UP, 0.9), mul(FWD, -0.9))), 0.2, 0.09, col);
    }
  }
  if(R.tail){
    var tb = add(J.pel, add(mul(FWD, -R.pelD*0.55), mul(UP, 0.02)));
    var tw = Math.sin(T*3 + f.phase);
    var t1 = add(tb, add(mul(FWD, -0.42), add(mul(RGT, tw*0.28), mul(UP, 0.34))));
    var t2 = add(t1, add(mul(FWD, -0.36), add(mul(RGT, -tw*0.3), mul(UP, 0.12))));
    limbTaper(tb, t1, 0.15, 0.11, col);
    limbTaper(t1, t2, 0.11, 0.06, col);
    pyr(t2, nrm(mul(FWD, -1)), 0.2, 0.09, col);
  }
  if(R.claws){
    var HD = [[J.haL, J.elL], [J.haR, J.elR]];
    for(i = 0; i < 2; i++){
      var cd = nrm(sub(HD[i][0], HD[i][1]));
      pyr(add(HD[i][0], mul(cd, R.fistW*0.62)), cd, 0.22*R.scale, 0.09, col);
    }
  }
  if(R.blade){
    var BD = [[J.haL, J.elL], [J.haR, J.elR]];
    for(i = 0; i < 2; i++){
      var bd = nrm(sub(BD[i][0], BD[i][1]));
      var bt = add(BD[i][0], mul(bd, 1.0*R.scale));
      limbTaper(BD[i][0], bt, 0.09, 0.015, col);
      lineSeg(add(BD[i][0], mul(UP, 0.05)), add(bt, mul(UP, 0.02)), col, 1.1, 0.9, 2);
    }
  }
  if(R.thruster){
    var bp = add(J.uch, mul(FWD, -R.chestD*0.62));
    boxCC3(bp, RGT, UP, FWD, R.chestW*0.5, 0.4, 0.16, col);
    for(sgn = -1; sgn <= 1; sgn += 2){
      var fl2 = 0.3 + 0.22*Math.abs(Math.sin(T*21 + sgn));
      var f0 = add(bp, mul(RGT, sgn*0.14));
      lineSeg(f0, add(f0, add(mul(FWD, -0.16), mul(UP, -fl2))), '#b6ffd0', 2, 0.8, 2);
    }
  }
  // arms
  limbTaper(J.shL, J.elL, R.ua, R.la*1.08, col);
  limbTaper(J.elL, J.haL, R.la, R.la*0.9, col);
  fistBox(J.haL, J.elL, R.fistW, col);
  limbTaper(J.shR, J.elR, R.ua, R.la*1.08, col);
  limbTaper(J.elR, J.haR, R.la, R.la*0.9, col);
  fistBox(J.haR, J.elR, R.fistW, col);
  // legs
  limbTaper(J.hpL, J.knL, R.th1, R.ca1*1.06, col);
  limbTaper(J.knL, J.ftL, R.ca1, R.ca2, col);
  boxCC3(add(J.ftL, mul(FWD, R.footD*0.18)), RGT, UP, FWD, R.footW, 0.15, R.footD, col);
  limbTaper(J.hpR, J.knR, R.th1, R.ca1*1.06, col);
  limbTaper(J.knR, J.ftR, R.ca1, R.ca2, col);
  boxCC3(add(J.ftR, mul(FWD, R.footD*0.18)), RGT, UP, FWD, R.footW, 0.15, R.footD, col);
  // player pin marker (human controlled only)
  if(f.ctrl === 'p1' || f.ctrl === 'p2'){
    var pc2 = f.ctrl === 'p1' ? '#39ff6e' : '#ffd23f';
    var pin = add(J.hed, mul(UP, R.headH*0.5 + 0.75));
    pyr(pin, mul(UP, -1), 0.26, 0.2, pc2);
    lineSeg(pin, add(pin, mul(UP, 0.24)), pc2, 1.4, 0.9, 2);
  }
}

// ============================================================
// 12 // AUDIO + RUMBLE
// ============================================================
var ACX = null;
function audio(){
  if(!ACX){
    try{ ACX = new (window.AudioContext || window.webkitAudioContext)(); }catch(e){}
  }
  return ACX;
}
function tone(a, type, f0, f1, dur, vol){
  var t = a.currentTime, o = a.createOscillator(), g = a.createGain();
  o.type = type;
  o.frequency.setValueAtTime(f0, t);
  o.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t + dur);
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.0008, t + dur);
  o.connect(g); g.connect(a.destination);
  o.start(t); o.stop(t + dur + 0.02);
}
function snd(n){
  var a = audio();
  if(!a) return;
  try{
    if(n === 'hit'){ tone(a, 'square', 240, 70, 0.10, 0.14); }
    else if(n === 'block'){ tone(a, 'square', 110, 90, 0.08, 0.10); }
    else if(n === 'boom'){ tone(a, 'sawtooth', 120, 30, 0.35, 0.18); }
    else if(n === 'swoosh'){ tone(a, 'sine', 900, 200, 0.18, 0.05); }
    else if(n === 'tele'){ tone(a, 'sine', 300, 1200, 0.12, 0.05); }
    else if(n === 'ko'){ tone(a, 'sawtooth', 160, 25, 0.7, 0.2); }
    else if(n === 'bell'){ tone(a, 'square', 660, 660, 0.12, 0.09); }
    else if(n === 'click'){ tone(a, 'square', 500, 500, 0.04, 0.05); }
  }catch(e){}
}
function rumble(idx, ms, mag){
  try{
    var gps = navigator.getGamepads && navigator.getGamepads();
    if(!gps) return;
    var gp = null, n = 0, i;
    for(i = 0; i < gps.length; i++){
      if(gps[i] && gps[i].connected){
        if(n === idx){ gp = gps[i]; break; }
        n++;
      }
    }
    if(gp && gp.vibrationActuator && gp.vibrationActuator.playEffect){
      gp.vibrationActuator.playEffect('dual-rumble',
        { duration: ms, strongMagnitude: mag, weakMagnitude: mag * 0.7 });
    }
  }catch(e){}
}

// ============================================================
// 13 // INPUT : keyboard, dual gamepads, touch
// ============================================================
function pollPads(){
  var gps = (navigator.getGamepads && navigator.getGamepads()) || [];
  var list = [], n = 0, i, j;
  for(i = 0; i < gps.length && n < 4; i++){
    var gp = gps[i];
    if(!gp || !gp.buttons || gp.connected === false) continue;
    var B = gp.buttons;
    var bd = function(jj){
      var x = B[jj];
      return !!(x && (x.pressed ||
        (typeof x.value === 'number' && x.value > ((jj === 6 || jj === 7) ? 0.35 : 0.5))));
    };
    var st = { b: [], p: [], ax: 0, ay: 0, pL: false, pR: false };
    for(j = 0; j < 18; j++){
      var d = j < B.length ? bd(j) : false;
      st.b[j] = d;
      st.p[j] = d && !PDP[n][j];
    }
    var ax = (gp.axes && gp.axes.length > 0) ? gp.axes[0] : 0;
    var ay = (gp.axes && gp.axes.length > 1) ? gp.axes[1] : 0;
    if(Math.abs(ax) < 0.24){ ax = 0; }
    if(Math.abs(ay) < 0.24){ ay = 0; }
    if(bd(14)){ ax = -1; } if(bd(15)){ ax = 1; }
    if(bd(12)){ ay = -1; } if(bd(13)){ ay = 1; }
    var pax = (typeof PDP[n].ax === 'number') ? PDP[n].ax : 0;
    st.ax = ax; st.ay = ay;
    st.pL = (ax < -0.5) && !(pax < -0.5);
    st.pR = (ax > 0.5) && !(pax > 0.5);
    for(j = 0; j < 18; j++){ PDP[n][j] = st.b[j]; }
    PDP[n].ax = ax;
    list.push(st);
    n++;
  }
  PADS = list;
}
function pd(i, b){ return !!(PADS[i] && PADS[i].b[b]); }
function pp(i, b){ return !!(PADS[i] && PADS[i].p[b]); }
function anyPadEdge(b){
  for(var i = 0; i < PADS.length; i++){ if(pp(i, b)){ return true; } }
  return false;
}
function menuEdge(){ return anyPadEdge(9); }
function viewEdge(){
  if(kE('KeyV')) return true;
  return anyPadEdge(8);
}
function cycleView(){
  VI = (VI + 1) % VIEWS.length;
  CAM.yaw = VIEWS[VI].yaw; CAM.pit = VIEWS[VI].pit; CAM.dist = VIEWS[VI].dist;
  snd('click');
}

// human control : merges gamepad slot + keyboard slot
function humanCtl(f, which){
  if(!f) return;
  var mvx = 0, mvz = 0;
  var punch = false, kick = false, def = false, jump = false;
  var sp1e = false, sp2e = false;
  var pi = (which === 'p1') ? 0 : 1;
  var P = PADS[pi];
  if(P){
    mvx += P.ax; mvz += -P.ay;
    kick = kick || P.b[0];
    punch = punch || P.b[1];
    def = def || P.b[2];
    jump = jump || P.b[3];
    sp1e = sp1e || P.p[7];
    sp2e = sp2e || P.p[6];
  }
  if(which === 'p1'){
    if(kD('KeyW')){ mvz += 1; } if(kD('KeyS')){ mvz -= 1; }
    if(kD('KeyA')){ mvx -= 1; } if(kD('KeyD')){ mvx += 1; }
    if(GAME.mode === '1p'){
      if(kD('ArrowUp')){ mvz += 1; } if(kD('ArrowDown')){ mvz -= 1; }
      if(kD('ArrowLeft')){ mvx -= 1; } if(kD('ArrowRight')){ mvx += 1; }
    }
    punch = punch || kD('KeyJ');
    kick = kick || kD('KeyK');
    def = def || kD('KeyL');
    jump = jump || kD('KeyI') || kD('Space');
    sp1e = sp1e || kE('KeyU');
    sp2e = sp2e || kE('KeyO');
  } else {
    if(kD('ArrowUp')){ mvz += 1; } if(kD('ArrowDown')){ mvz -= 1; }
    if(kD('ArrowLeft')){ mvx -= 1; } if(kD('ArrowRight')){ mvx += 1; }
    punch = punch || kD('KeyN') || kD('Numpad1');
    kick = kick || kD('KeyM') || kD('Numpad2');
    def = def || kD('Comma') || kD('Numpad3');
    jump = jump || kD('Period') || kD('Numpad5') || kD('Numpad0');
    sp1e = sp1e || kE('Numpad4');
    sp2e = sp2e || kE('Numpad6');
  }
  f.mv = [clamp(mvx, -1, 1), clamp(mvz, -1, 1)];
  f.blockHold = def;
  if(GAME.state !== 'fight' || GAME.paused) return;
  if(f.state === 'idle' || f.state === 'walk'){
    if(def){ f.state = 'block'; f.t = 0; return; }
    if(f.cool <= 0){
      if(punch){
        var nm = f.lastP === 'jab' ? 'cross' : 'jab';
        if(f.tryMove(nm)){ f.lastP = nm; }
      } else if(kick){
        f.tryMove('kick');
      } else if(jump){
        f.tryMove('jumpatk');
      } else if(sp1e){
        f.tryMove((CHARSPEC[f.R.name] || ['sp1','sp2'])[0]);
      } else if(sp2e){
        f.tryMove((CHARSPEC[f.R.name] || ['sp1','sp2'])[1]);
      }
    }
  }
}

var GAMEKEYS = { KeyW:1, KeyA:1, KeyS:1, KeyD:1, ArrowUp:1, ArrowDown:1,
  ArrowLeft:1, ArrowRight:1, Space:1, KeyJ:1, KeyK:1, KeyL:1, KeyI:1,
  KeyU:1, KeyO:1, KeyV:1, KeyP:1, Enter:1, Escape:1, KeyT:1, KeyC:1,
  KeyN:1, KeyM:1, Comma:1, Period:1, Numpad0:1, Numpad1:1, Numpad2:1,
  Numpad3:1, Numpad4:1, Numpad5:1, Numpad6:1, KeyX:1, KeyQ:1, KeyZ:1 };

function bindKeys(){
  window.addEventListener('keydown', function(e){
    if(GAMEKEYS[e.code]){ e.preventDefault(); }
    if(!KEYS[e.code]){ KEDGE[e.code] = true; }
    KEYS[e.code] = true;
    try{ var a = audio(); if(a && a.state === 'suspended'){ a.resume(); } }catch(err){}
  });
  window.addEventListener('keyup', function(e){ KEYS[e.code] = false; });
  window.addEventListener('blur', function(){ KEYS = {}; });
  document.addEventListener('pointerdown', function(e){
    if(e.target && TMAP[e.target.id]){ return; }
    if(GAME.state === 'title' || GAME.state === 'win'){ TAP = true; }
  });
  window.addEventListener('touchstart', function(){
    if(!TOUCHON){ TOUCHON = true; }
  }, { passive: true });
  window.addEventListener('gamepadconnected', function(){ snd('click'); });
  window.addEventListener('gamepaddisconnected', function(){ snd('click'); });
}

var TMAP = { tU:'KeyW', tD:'KeyS', tL:'KeyA', tR:'KeyD', tY:'KeyI',
  tX:'KeyL', tB:'KeyJ', tA:'KeyK', tRT:'KeyU', tLT:'KeyO', tV:'KeyV', tP:'KeyP' };

function bindTouch(){
  var k;
  for(k in TMAP){
    (function(code, el){
      if(!el){ return; }
      var dn = function(e){ e.preventDefault(); e.stopPropagation(); KSET(code, true); };
      var up = function(e){ e.preventDefault(); e.stopPropagation(); KSET(code, false); };
      el.addEventListener('pointerdown', dn);
      el.addEventListener('pointerup', up);
      el.addEventListener('pointerleave', up);
      el.addEventListener('pointercancel', up);
    })(TMAP[k], $(k));
  }
}

// ============================================================
// 14 // GAME FLOW (title / select / match / rounds / campaign)
// ============================================================
function banner(a, b, dur){
  setTxt(EL.banner, a);
  setTxt(EL.banner2, b || '');
  sA(EL.banner, 'visibility', 'visible');
  sA(EL.banner2, 'visibility', 'visible');
  BANT = (dur === undefined) ? 2.0 : dur;
}
function hideBanner(){
  sA(EL.banner, 'visibility', 'hidden');
  sA(EL.banner2, 'visibility', 'hidden');
  BANT = 0;
}

function upTitleUI(){
  var n = PADS.length;
  setTxt(EL.tPads, n === 0 ? 'INPUT : KEYBOARD / TOUCH' :
    (n === 1 ? 'GAMEPAD DETECTED : 1' : 'GAMEPADS DETECTED : ' + n));
  var s;
  if(n === 0){ s = 'PRESS ENTER / TAP TO FIGHT'; }
  else if(n === 1){ s = 'PAD START = 1 PLAYER (PICK YOUR FIGHTER)'; }
  else { s = 'PAD 1 START = 1 PLAYER  //  PAD 2 START = 2 PLAYER'; }
  setTxt(EL.pressL, s);
  sA(EL.pressL, 'opacity', (0.55 + 0.45 * Math.abs(Math.sin(T * 2.4))).toFixed(2));
  var tw = 'C KEY / PAD LB OR LT = 2 PLAYER VERSUS';
  if(n === 1){ tw = 'C / LB / LT = 2P : P1 PAD + P2 KEYBOARD'; }
  setTxt(EL.tTwo, tw);
}

function beginGame(mode){
  snd('click');
  GAME.mode = mode;
  GAME.p1lock = false; GAME.p2lock = false;
  GAME.p1sel = 0;
  GAME.p2sel = (mode === '2p') ? 1 : 0;
  GAME.selT = 0;
  IGN = 0.35;
  if(mode === '2p' || PADS.length > 0){
    gotoSelect();
  } else {
    // classic no-pad flow : straight in as VANGUARD-01
    GAME.p1sel = 0;
    GAME.oppList = [1, 2, 3, 4, 5];
    GAME.ei = 0;
    startMatch();
  }
}

function gotoSelect(){
  GAME.state = 'select';
  sA(EL.titleUI, 'visibility', 'hidden');
  sA(EL.selectUI, 'visibility', 'visible');
  hideBanner();
  GAME.selT = 0;
  PRE = [null, null];
  refreshPreview(0);
  if(GAME.mode === '2p'){ refreshPreview(1); }
  var h;
  if(GAME.mode === '2p'){
    h = 'P1: PAD1 DPAD/STICK or A·D CYCLE — A/B/LT/MENU LOCK — X UNLOCK';
    h += '   //   P2: PAD2 or ARROWS — N LOCK — M UNLOCK   //   VIEW/ESC BACK';
  } else {
    h = 'PICK YOUR FIGHTER : CYCLE + CONFIRM — YOU WILL FACE THE OTHER 5';
    h += '   //   PAD: DPAD/STICK or LB/RB CYCLE, A/B/LT LOCK, X UNLOCK';
  }
  setTxt(EL.selHint, h);
}

function refreshPreview(s){
  var f = new Fighter(buildRigFor(s === 0 ? GAME.p1sel : GAME.p2sel),
                      s === 0 ? 'p1' : 'p2');
  f.x = (s === 0) ? -2.3 : 2.3;
  f.z = 0; f.yaw = (s === 0) ? Math.PI/2 : -Math.PI/2;
  PRE[s] = f;
}

function selSide(s){
  var dl = false, dr = false, ok = false, back = false;
  if(PADS[s]){
    if(pp(s, 14) || PADS[s].pL || pp(s, 4)){ dl = true; }
    if(pp(s, 15) || PADS[s].pR || pp(s, 5)){ dr = true; }
    if(pp(s, 0) || pp(s, 1) || pp(s, 9) || pp(s, 6)){ ok = true; }
    if(pp(s, 2)){ back = true; }
  }
  if(s === 0){
    if(kE('KeyA')){ dl = true; }
    if(kE('KeyD')){ dr = true; }
    if(GAME.mode === '1p'){
      if(kE('ArrowLeft')){ dl = true; }
      if(kE('ArrowRight')){ dr = true; }
    }
    if(kE('KeyJ') || kE('Enter')){ ok = true; }
    if(kE('KeyZ')){ back = true; }
  } else {
    if(kE('ArrowLeft')){ dl = true; }
    if(kE('ArrowRight')){ dr = true; }
    if(kE('KeyN')){ ok = true; }
    if(kE('KeyM')){ back = true; }
  }
  var locked = (s === 0) ? GAME.p1lock : GAME.p2lock;
  if(!locked){
    if(dl || dr){
      if(s === 0){ GAME.p1sel = (GAME.p1sel + (dr ? 1 : 5)) % 6; refreshPreview(0); }
      else { GAME.p2sel = (GAME.p2sel + (dr ? 1 : 5)) % 6; refreshPreview(1); }
      snd('click');
    }
    if(ok){
      if(s === 0){ GAME.p1lock = true; } else { GAME.p2lock = true; }
      snd('bell');
    }
  } else if(back){
    if(s === 0){ GAME.p1lock = false; } else { GAME.p2lock = false; }
    snd('click');
  }
}

function launchMatch(){
  if(GAME.mode === '1p'){
    GAME.oppList = [];
    for(var i = 0; i < 6; i++){ if(i !== GAME.p1sel){ GAME.oppList.push(i); } }
    GAME.ei = 0;
  }
  startMatch();
}

function resetF(f, x, yaw){
  f.x = x; f.z = 0; f.y = 0; f.yaw = yaw;
  f.hp = f.maxhp;
  f.state = 'intro'; f.anim = null; f.t = 0;
  f.mv = [0, 0]; f.cool = 0.6;
  f.blockHold = false; f.blockT = 0;
  f.wh = []; f.evI = 0; f.y = 0;
  f.combo = 0; f.comboT = 0; f.prevTips = null;
}

function resetRound(){
  resetF(PL, -2.5, Math.PI/2);
  resetF(EN, 2.5, -Math.PI/2);
  GAME.timer = 60;
}

function startMatch(){
  PRE = [null, null];
  sA(EL.selectUI, 'visibility', 'hidden');
  SPARKS = []; RINGS = []; PROJ = [];
  PL = new Fighter(buildRigFor(GAME.p1sel), 'p1');
  if(GAME.mode === '2p'){
    EN = new Fighter(buildRigFor(GAME.p2sel), 'p2');
  } else {
    EN = new Fighter(buildRigFor(GAME.oppList[GAME.ei]), 'cpu');
  }
  GAME.plw = 0; GAME.enw = 0; GAME.round = 1;
  GAME.paused = false;
  resetRound();
  GAME.state = 'intro'; GAME.introT = 0; GAME.fightShown = false;
  banner('ROUND 1', GAME.mode === '2p' ? 'P1 VS P2' : 'VS ' + EN.R.name, 1.4);
  snd('swoosh');
}

function toTitle(){
  GAME.state = 'title';
  GAME.paused = false;
  PL = null; EN = null; PRE = [null, null];
  SPARKS = []; RINGS = []; PROJ = [];
  hideBanner();
  sA(EL.selectUI, 'visibility', 'hidden');
  sA(EL.titleUI, 'visibility', 'visible');
  snd('click');
}

function upTitle(dt){
  upTitleUI();
  if(IGN > 0){ return; }
  var i;
  for(i = 0; i < PADS.length; i++){
    // START / A / B on pad 1 begins 1P, on pad 2 joins 2P.
    // LB or LT on ANY pad selects 2 PLAYER VERSUS.
    if(pp(i, 9) || pp(i, 0) || pp(i, 1)){
      beginGame(i === 0 ? '1p' : '2p');
      return;
    }
    if(pp(i, 4) || pp(i, 6)){
      beginGame('2p');
      return;
    }
  }
  if(kE('Enter') || TAP){ beginGame('1p'); return; }
  if(kE('KeyC')){ beginGame('2p'); return; }
}

function updSelectUI(){
  var i, o, y;
  for(i = 0; i < 6; i++){
    o = (GAME.p1sel === i || (GAME.mode === '2p' && GAME.p2sel === i)) ? 1 : 0.42;
    sA(SR[i], 'opacity', o.toFixed(2));
    sA(SS[i], 'opacity', (o * 0.9).toFixed(2));
  }
  y = 268 + GAME.p1sel * 96 + 26;
  sA(EL.selP1Cur, 'transform', 'translate(766,' + y + ')');
  sA(EL.selP1Cur, 'opacity', GAME.p1lock ? '1' : (0.55 + 0.45 * Math.sin(T * 6)).toFixed(2));
  setTxt(EL.selP1Ready, GAME.p1lock ? 'P1 READY : ' + FULLROSTER[GAME.p1sel].name
                                    : 'P1 : ' + FULLROSTER[GAME.p1sel].name);
  sA(EL.selP1Ready, 'opacity', '1');
  if(GAME.mode === '2p'){
    y = 268 + GAME.p2sel * 96 + 26;
    sA(EL.selP2Cur, 'transform', 'translate(1154,' + y + ')');
    sA(EL.selP2Cur, 'opacity', GAME.p2lock ? '1' : (0.55 + 0.45 * Math.sin(T * 6 + 1)).toFixed(2));
    setTxt(EL.selP2Ready, GAME.p2lock ? 'P2 READY : ' + FULLROSTER[GAME.p2sel].name
                                      : 'P2 : ' + FULLROSTER[GAME.p2sel].name);
    sA(EL.selP2Ready, 'opacity', '1');
  } else {
    sA(EL.selP2Cur, 'opacity', '0');
    sA(EL.selP2Ready, 'opacity', '0');
  }
}

function upSelect(dt){
  if(PRE[0]){ PRE[0].think(dt, PRE[1] || { x: 2.2, z: 0 }); }
  if(PRE[1]){ PRE[1].think(dt, PRE[0] || { x: -2.2, z: 0 }); }
  if(IGN > 0){ updSelectUI(); return; }
  if(anyPadEdge(8) || kE('Escape')){ toTitle(); return; }
  selSide(0);
  if(GAME.mode === '2p'){ selSide(1); }
  var all = (GAME.mode === '2p') ? (GAME.p1lock && GAME.p2lock) : GAME.p1lock;
  if(all){
    GAME.selT += dt;
    if(GAME.selT > 0.75){ launchMatch(); return; }
  } else {
    GAME.selT = 0;
  }
  updSelectUI();
}

function upIntro(dt){
  GAME.introT += dt;
  if(PL){ PL.think(dt, EN); }
  if(EN){ EN.think(dt, PL); }
  if(GAME.introT >= 1.05 && !GAME.fightShown){
    GAME.fightShown = true;
    if(PL){ PL.state = 'idle'; PL.t = 0; }
    if(EN){ EN.state = 'idle'; EN.t = 0; }
    banner('FIGHT', '', 0.7);
    snd('bell');
  }
  if(GAME.introT >= 1.55){
    GAME.state = 'fight';
    GAME.fightShown = false;
    GAME.timer = 60;
  }
}

function upFight(dt){
  if(menuEdge() || kE('KeyP') || kE('Escape')){
    GAME.paused = !GAME.paused;
    snd('click');
    if(GAME.paused){
      banner('PAUSED', 'MENU / P = RESUME — X = QUIT — V = VIEW', 900);
    } else {
      hideBanner();
    }
  }
  if(GAME.paused){
    if(anyPadEdge(2) || kE('KeyX') || kE('KeyQ')){ toTitle(); }
    return;
  }
  humanCtl(PL, 'p1');
  if(GAME.mode === '2p'){
    humanCtl(EN, 'p2');
  } else {
    aiThink(EN, PL, dt);
  }
  if(PL){ PL.think(dt, EN); }
  if(EN){ EN.think(dt, PL); }
  resolveAttacks();
  separation();
  updProj(dt);
  if(PL){ PL.me = Math.min(100, PL.me + 2.6 * dt); }
  if(EN){ EN.me = Math.min(100, EN.me + 2.6 * dt); }
  GAME.timer -= dt;
  if(GAME.timer <= 0 && GAME.state === 'fight'){
    GAME.timer = 0;
    timeUp();
  }
}

function matchOver(){
  if(GAME.mode === '2p'){
    GAME.state = 'post';
    banner(GAME.plw >= 2 ? 'P1 WINS' : 'P2 WINS',
           'MENU = REMATCH // LB OR LT = SELECT // X = TITLE', 900);
    snd('ko');
  } else if(GAME.plw >= 2){
    if(GAME.ei >= GAME.oppList.length - 1){
      GAME.state = 'win';
      banner('CAMPAIGN COMPLETE',
             'ALL CHALLENGERS DEFEATED — MENU / ENTER / TAP = TITLE', 900);
      snd('bell');
    } else {
      GAME.ei++;
      GAME.state = 'next';
      GAME.nextT = 0;
      banner('CHALLENGER ' + (GAME.ei + 1) + ' / ' + GAME.oppList.length,
             'NEXT : ' + FULLROSTER[GAME.oppList[GAME.ei]].name, 2.4);
      snd('swoosh');
    }
  } else {
    GAME.state = 'lose';
    banner('GAME OVER', 'MENU / ENTER = CONTINUE — X / ESC = TITLE', 900);
    snd('ko');
  }
}

function upEnd(dt){
  GAME.koT += dt;
  if(PL){ PL.think(dt, EN); }
  if(EN){ EN.think(dt, PL); }
  if(GAME.koT > 2.6){
    if(GAME.plw >= 2 || GAME.enw >= 2){
      matchOver();
    } else {
      GAME.round++;
      resetRound();
      GAME.state = 'intro';
      GAME.introT = 0; GAME.fightShown = false;
      banner('ROUND ' + GAME.round,
             label(PL) + ' ' + GAME.plw + ' — ' + GAME.enw + ' ' + label(EN), 1.4);
    }
  }
}

function upNext(dt){
  GAME.nextT += dt;
  if(PL){ PL.think(dt, EN); }
  if(EN){ EN.think(dt, PL); }
  if(GAME.nextT > 2.4){
    PL.hp = PL.maxhp; PL.me = 30; PL.combo = 0; PL.comboT = 0;
    EN = new Fighter(buildRigFor(GAME.oppList[GAME.ei]), 'cpu');
    GAME.plw = 0; GAME.enw = 0; GAME.round = 1;
    resetRound();
    GAME.state = 'intro'; GAME.introT = 0; GAME.fightShown = false;
    banner('ROUND 1', 'VS ' + EN.R.name, 1.4);
  }
}

function upPost(dt){
  if(PL){ PL.think(dt, EN); }
  if(EN){ EN.think(dt, PL); }
  if(menuEdge() || kE('Enter') || TAP){
    PL.hp = PL.maxhp; EN.hp = EN.maxhp;
    PL.me = 25; EN.me = 25;
    GAME.plw = 0; GAME.enw = 0; GAME.round = 1;
    resetRound();
    GAME.state = 'intro'; GAME.introT = 0; GAME.fightShown = false;
    banner('ROUND 1', 'P1 VS P2 — REMATCH', 1.4);
    snd('bell');
    return;
  }
  if(anyPadEdge(4) || anyPadEdge(6) || kE('KeyC') || kE('Escape')){
    gotoSelect();
    return;
  }
  if(anyPadEdge(2) || kE('KeyX')){ toTitle(); }
}

function upLose(dt){
  if(PL){ PL.think(dt, EN); }
  if(EN){ EN.think(dt, PL); }
  if(menuEdge() || kE('Enter') || TAP){
    PL.hp = PL.maxhp; PL.me = 30;
    EN = new Fighter(buildRigFor(GAME.oppList[GAME.ei]), 'cpu');
    GAME.plw = 0; GAME.enw = 0; GAME.round = 1;
    resetRound();
    GAME.state = 'intro'; GAME.introT = 0; GAME.fightShown = false;
    banner('ROUND 1', 'VS ' + EN.R.name, 1.4);
    snd('bell');
    return;
  }
  if(anyPadEdge(2) || kE('KeyX') || kE('Escape')){ toTitle(); }
}

function upWin(dt){
  if(PL){ PL.think(dt, EN); }
  if(EN){ EN.think(dt, PL); }
  if(menuEdge() || kE('Enter') || TAP){ toTitle(); }
}

// ============================================================
// 15 // UPDATE + HUD + RENDER
// ============================================================
function update(dt){
  if(IGN > 0){ IGN -= dt; }
  pollPads();
  PADN = PADS.length === 0 ? 'KB' : (PADS.length === 1 ? 'PAD x1' : 'PADS x' + PADS.length);
  if(kE('KeyT')){ TOUCHON = !TOUCHON; snd('click'); }
  var tv = TOUCHON && GAME.state !== 'title';
  sA(EL.touchUI, 'visibility', tv ? 'visible' : 'hidden');
  if(viewEdge()){ cycleView(); }
  // attract camera drift on menus
  if(GAME.state === 'title' || GAME.state === 'select'){
    CAM.yaw = VIEWS[VI].yaw + Math.sin(T * 0.12) * 0.4;
    CAM.pit = VIEWS[VI].pit + Math.sin(T * 0.07) * 0.05;
  }
  switch(GAME.state){
    case 'title':  upTitle(dt); break;
    case 'select': upSelect(dt); break;
    case 'intro':  upIntro(dt); break;
    case 'fight':  upFight(dt); break;
    case 'end':    upEnd(dt); break;
    case 'next':   upNext(dt); break;
    case 'post':   upPost(dt); break;
    case 'win':    upWin(dt); break;
    case 'lose':   upLose(dt); break;
  }
  if(!GAME.paused){ updFX(dt); }
  if(BANT > 0){
    BANT -= dt;
    if(BANT <= 0){
      sA(EL.banner, 'visibility', 'hidden');
      sA(EL.banner2, 'visibility', 'hidden');
    }
  }
  FLASH = Math.max(0, FLASH - dt * 2.2);
  sA(EL.flash, 'opacity', (FLASH * 0.5).toFixed(2));
  if(SHAKE > 0){
    SHX = (Math.random() - 0.5) * SHAKE * 46;
    SHY = (Math.random() - 0.5) * SHAKE * 30;
    SHAKE = Math.max(0, SHAKE - dt * 1.6);
  } else { SHX = 0; SHY = 0; }
  if(MVT > 0){
    MVT -= dt;
    if(MVT < 0){ MVT = 0; }
    sA(EL.mvn, 'opacity', Math.min(1, MVT).toFixed(2));
  }
}

function updateHUD(){
  var ln = 'VANGUARD-01', lc = '#39ff6e', rn = 'CHALLENGER', rc = '#ffd23f';
  var lw = 752, rw = 752, lme = 0, rme = 0;
  if(GAME.state === 'select'){
    ln = FULLROSTER[GAME.p1sel].name; lc = FULLROSTER[GAME.p1sel].col;
    if(GAME.mode === '2p'){
      rn = FULLROSTER[GAME.p2sel].name; rc = FULLROSTER[GAME.p2sel].col;
    } else {
      rn = 'THE OTHER 5'; rc = '#ffd23f';
    }
    lme = 90; rme = 90;
  } else if(PL && EN){
    ln = PL.R.name; lc = PL.R.col;
    rn = EN.R.name; rc = EN.R.col;
    lw = Math.round(752 * PL.hp / PL.maxhp);
    rw = Math.round(752 * EN.hp / EN.maxhp);
    lme = Math.round(3.6 * PL.me);
    rme = Math.round(3.6 * EN.me);
  }
  setTxt(EL.nameL, ln); sA(EL.nameL, 'fill', lc);
  setTxt(EL.nameR, rn); sA(EL.nameR, 'fill', rc);
  sA(EL.hpLbox, 'stroke', lc);
  sA(EL.hpL, 'stroke', lc); sA(EL.hpL, 'fill', lc); sA(EL.hpL, 'width', lw);
  sA(EL.hpRbox, 'stroke', rc);
  sA(EL.hpR, 'stroke', rc); sA(EL.hpR, 'fill', rc);
  sA(EL.hpR, 'width', rw); sA(EL.hpR, 'x', String(1876 - rw));
  sA(EL.meterL, 'width', lme);
  sA(EL.meterR, 'width', rme); sA(EL.meterR, 'x', String(1880 - rme));
  sA(EL.dL0, 'fill', GAME.plw >= 1 ? lc : 'none');
  sA(EL.dL1, 'fill', GAME.plw >= 2 ? lc : 'none');
  sA(EL.dR0, 'fill', GAME.enw >= 1 ? rc : 'none');
  sA(EL.dR1, 'fill', GAME.enw >= 2 ? rc : 'none');
  sA(EL.dL0, 'stroke', lc); sA(EL.dL1, 'stroke', lc);
  sA(EL.dR0, 'stroke', rc); sA(EL.dR1, 'stroke', rc);
  var tv = (GAME.state === 'fight' || GAME.state === 'intro' || GAME.state === 'end')
    ? String(Math.max(0, Math.ceil(GAME.timer))) : '60';
  setTxt(EL.tmr, tv);
  if(PL && PL.combo >= 2 && PL.comboT > 0){
    setTxt(EL.combo, PL.combo + ' HITS'); sA(EL.combo, 'fill', lc);
  } else { setTxt(EL.combo, ''); }
  if(EN && EN.combo >= 2 && EN.comboT > 0){
    setTxt(EL.comboR, EN.combo + ' HITS'); sA(EL.comboR, 'fill', rc);
  } else { setTxt(EL.comboR, ''); }
  setTxt(EL.padS, 'PADS: ' + PADN);
  sA(EL.rec, 'fill-opacity', Math.sin(T * 2.4) > -0.2 ? '1' : '0.15');
}

function render(){
  cacheCamRot();
  DL.length = 0;
  try{ drawArena(); }catch(e){}
  if(GAME.state === 'select'){
    if(PRE[0]){ try{ drawFighter(PRE[0]); }catch(e){} }
    if(PRE[1]){ try{ drawFighter(PRE[1]); }catch(e){} }
  } else {
    if(PL){ try{ drawFighter(PL); }catch(e){} }
    if(EN){ try{ drawFighter(EN); }catch(e){} }
  }
  try{ drawFX(); }catch(e){}
  DL.sort(function(a, b){ return (a.l - b.l) || (b.z - a.z); });
  var s = '', i;
  for(i = 0; i < DL.length; i++){ s += DL[i].s; }
  var bid = ROT[2];                 // rewrite the oldest buffer
  ELBUF[bid].innerHTML = s;
  ROT = [bid, ROT[0], ROT[1]];      // just-written becomes newest
  setBuf(EL.uA, '#buf' + ROT[0]);
  setBuf(EL.uB, '#buf' + ROT[1]);
  setBuf(EL.uC, '#buf' + ROT[2]);
  updateHUD();
}

// ============================================================
// 16 // SELECT SCREEN BUILD + BOOT + MAIN LOOP
// ============================================================
function buildSelectUI(){
  var g = EL.selRows, s = '', i, y;
  for(i = 0; i < 6; i++){
    y = 268 + i * 96;
    var F = FULLROSTER[i], st = FULLSTAT[i];
    s += '<text id="sr' + i + '" x="960" y="' + (y + 36) +
         '" font-size="36" fill="' + F.col + '" letter-spacing="7" text-anchor="middle" opacity="0.42">' +
         F.name + '</text>';
    s += '<text id="ss' + i + '" x="960" y="' + (y + 64) +
         '" font-size="15" fill="#1f7a3d" letter-spacing="3" text-anchor="middle" opacity="0.4">HP ' +
         st.hp + ' // PWR ' + st.dmg.toFixed(2) + ' // SPD ' + st.spd.toFixed(2) + '</text>';
    s += '<line x1="620" y1="' + (y + 78) + '" x2="1300" y2="' + (y + 78) +
         '" stroke="#135c2e" stroke-width="1"/>';
  }
  g.innerHTML = s;
  for(i = 0; i < 6; i++){ SR[i] = $('sr' + i); SS[i] = $('ss' + i); }
}

function init(){
  var ids = ['nameL','nameR','hpL','hpR','hpLbox','hpRbox','meterL','meterR',
    'tmr','rec','dL0','dL1','dR0','dR1','mvn','combo','comboR','padS',
    'banner','banner2','titleUI','selectUI','selRows','selP1Cur','selP2Cur',
    'selP1Ready','selP2Ready','selHint','flash','touchUI','tPads','pressL',
    'tTwo','uA','uB','uC'];
  var i;
  for(i = 0; i < ids.length; i++){ EL[ids[i]] = $(ids[i]); }
  ELBUF = [$('buf0'), $('buf1'), $('buf2')];
  buildArena();
  bindKeys();
  bindTouch();
  buildSelectUI();
  sA(EL.titleUI, 'visibility', 'visible');
  requestAnimationFrame(loop);
}

var last = 0;
function loop(now){
  if(!last){ last = now; }
  var dt = (now - last) / 1000;
  last = now;
  if(dt > 0.05){ dt = 0.05; }
  if(dt < 0){ dt = 0; }
  T += dt;
  FPS.acc += dt; FPS.n++;
  if(FPS.n >= 50){
    FPS.low = (FPS.acc / FPS.n) > 0.024;
    FPS.acc = 0; FPS.n = 0;
  }
  try{ update(dt); }catch(e){}
  try{ render(); }catch(e){}
  KEDGE = {};
  TAP = false;
  requestAnimationFrame(loop);
}

init();
